import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order, Village, Offer, OrderCategory, Restaurant, MenuItem, CartItem, District } from '../types';
import { OrderStatus, VehicleType } from '../types';
import { MENOFIA_DATA, DEFAULT_PRICING } from '../config/constants';

// React Leaflet
import { MapContainer, TileLayer, Marker } from 'react-leaflet';
import L from 'leaflet';

// Utils
import { stripFirestore, calculateDistance, compressImage, getRoadDistance } from '../utils';

// Services
import { db } from '../services/firebase';
import { 
  collection, addDoc, query, where, onSnapshot, 
  doc, updateDoc
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  MapPin, Bike, Check, 
  ChevronDown, ChevronRight, Star,
  User as UserIcon, MessageCircle, Loader2,
  Bot, History, Navigation2, UtensilsCrossed, 
  ShoppingBag, ArrowRight, ThumbsUp, PartyPopper,
  Plus, Minus, PhoneCall, Pill,
  Zap, Car, X, Navigation, Map as MapIcon,
  Camera, FileText, Search, Edit2, CheckCircle2,
  Utensils, Store, Trash2, ZoomIn, Download, ChevronLeft,
  Timer, Milestone
} from 'lucide-react';

// Components
import ProfileView from './ProfileView';
import ActivityView from './ActivityView';
import WalletView from './WalletView';
import ChatView from '../components/ChatView';
import AIAssistant from '../config/AIAssistant';

// --- Custom Components ---

const FullMenuModal: React.FC<{ url: string, onClose: () => void }> = ({ url, onClose }) => {
  useEffect(() => {
    // إضافة حالة لتاريخ المتصفح للتعامل مع زر الرجوع
    window.history.pushState({ modal: 'full-menu' }, '');

    const handlePopState = (event: PopStateEvent) => {
      onClose();
    };

    window.addEventListener('popstate', handlePopState);

    return () => {
      window.removeEventListener('popstate', handlePopState);
      if (window.history.state?.modal === 'full-menu') {
        window.history.back();
      }
    };
  }, [onClose]);

  return (
    <div className="fixed inset-0 z-[2000] bg-black/95 backdrop-blur-3xl flex flex-col animate-in fade-in duration-300">
      <div className="p-8 flex justify-between items-center text-white border-b border-white/10">
        <div className="flex gap-3">
           <button onClick={() => {
             const link = document.createElement('a');
             link.href = url;
             link.download = 'restaurant-menu.png';
             link.click();
           }} className="p-4 bg-emerald-600 rounded-2xl flex items-center gap-2 font-black text-xs shadow-lg active:scale-90 transition-all">
             <Download className="h-5 w-5" /> حفظ المنيو
           </button>
        </div>
        <button onClick={onClose} className="p-4 bg-white/10 rounded-2xl flex items-center gap-2 font-black text-xs hover:bg-white/20 active:scale-90 transition-all">
          إغلاق <ChevronLeft className="h-5 w-5" />
        </button>
      </div>
      <div className="flex-1 overflow-auto p-4 flex items-center justify-center no-scrollbar">
         <img 
           src={url} 
           className="max-w-full max-h-full object-contain shadow-[0_0_100px_rgba(0,0,0,0.5)] rounded-lg animate-in zoom-in duration-500" 
           alt="Restaurant Menu"
         />
      </div>
    </div>
  );
};

const PriceEstimateCard: React.FC<{ 
  distance: number, 
  duration: number, 
  price: number, 
  vehicle: VehicleType,
  loading: boolean 
}> = ({ price, vehicle, loading }) => {
  if (loading) return (
    <div className="bg-white p-8 rounded-[3rem] card-shadow border-2 border-emerald-100 flex items-center justify-center gap-4 animate-pulse">
       <Loader2 className="h-8 w-8 text-emerald-500 animate-spin" />
       <span className="font-black text-slate-400 text-sm tracking-tight">جاري حساب تكلفة المشوار...</span>
    </div>
  );

  return (
    <div className="bg-white p-10 rounded-[3.5rem] card-shadow border-2 border-emerald-500/20 animate-in zoom-in duration-500 relative overflow-hidden">
       <div className="absolute top-0 left-0 w-32 h-full bg-emerald-500/5 -skew-x-12 translate-x-[-50%]"></div>

       <div className="flex justify-between items-center relative z-10">
          <div className="text-right">
             <p className="text-[11px] font-black text-emerald-600 uppercase tracking-widest mb-1.5">التكلفة المتوقعة للمشوار</p>
             <h3 className="text-5xl font-black text-slate-900 tracking-tighter leading-none">{price} <span className="text-sm font-bold text-slate-400">ج.م</span></h3>
          </div>
          <div className="bg-emerald-500 text-white p-5 rounded-[2.2rem] shadow-xl shadow-emerald-200">
             {vehicle === 'CAR' ? <Car className="h-9 w-9" /> : vehicle === 'MOTORCYCLE' ? <Bike className="h-9 w-9" /> : <Zap className="h-9 w-9" />}
          </div>
       </div>
    </div>
  );
};

const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);

  useEffect(() => {
    window.history.pushState({ modal: 'rest-menu' }, '');
    const handlePop = () => onClose();
    window.addEventListener('popstate', handlePop);
    return () => window.removeEventListener('popstate', handlePop);
  }, [onClose]);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {showFullMenu && restaurant.menuImageURL && <FullMenuModal url={restaurant.menuImageURL} onClose={() => setShowFullMenu(false)} />}

       <div className="bg-[#0F172A] p-8 pt-14 text-white flex justify-between items-center shadow-xl shrink-0">
          <button onClick={() => window.history.back()} className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 transition-all"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category} • منوفية</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50 no-scrollbar pb-32">
          {restaurant.menuImageURL && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-[#10b981] p-6 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl active:scale-95 transition-all border-none">
               <div className="bg-white/20 p-4 rounded-2xl"><ZoomIn className="h-6 w-6" /></div>
               <div className="text-right">
                  <h4 className="font-black text-lg leading-tight">عرض المنيو الورقي</h4>
                  <p className="text-[10px] font-bold opacity-80 uppercase tracking-widest mt-1">تصفح صور قائمة الطعام كاملة</p>
               </div>
            </button>
          )}

          <div className="space-y-4">
             {restaurant.menu?.length > 0 ? restaurant.menu.map(item => (
               <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center group">
                  <div className="flex items-center gap-2">
                     <button onClick={() => addToCart(item)} className="p-3 bg-emerald-500 text-white rounded-2xl shadow-lg active:scale-75 transition-all"><Plus className="h-4 w-4" /></button>
                     <span className="font-black text-lg w-8 text-center text-slate-800">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                     <button onClick={() => removeFromCart(item.id)} className="p-3 bg-rose-50 text-rose-500 rounded-2xl active:scale-75 transition-all"><Minus className="h-4 w-4" /></button>
                  </div>
                  <div className="text-right flex items-center gap-4 flex-row-reverse text-right">
                     <div className="w-16 h-16 bg-slate-100 rounded-[1.5rem] overflow-hidden shrink-0 shadow-inner group-hover:scale-105 transition-transform">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <Utensils className="p-5 text-slate-300" />}
                     </div>
                     <div>
                        <p className="font-black text-slate-900 text-lg">{item.name}</p>
                        <p className="text-emerald-600 font-bold text-sm">{item.price} ج.م</p>
                     </div>
                  </div>
               </div>
             )) : (
               <div className="py-20 text-center text-slate-300 font-black border-4 border-dashed rounded-[3rem] bg-white/50">لا توجد أصناف رقمية معروضة حالياً</div>
             )}
          </div>
       </div>

       {cart.length > 0 && (
         <div className="fixed bottom-0 left-0 right-0 p-8 bg-white/80 backdrop-blur-xl border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-2xl z-50">
            <div className="flex justify-between items-center mb-6 px-4">
               <p className="text-3xl font-black text-slate-950">{total} <span className="text-sm font-bold text-slate-400">ج.م</span></p>
               <p className="text-xs font-black text-slate-400 uppercase tracking-widest">إجمالي الحساب</p>
            </div>
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-7 w-7" /> تأكيد طلب الطعام
            </button>
         </div>
       )}
    </div>
  );
};

const LocationSelector: React.FC<{
  label: string,
  helper: string,
  icon: React.ReactNode,
  iconBg: string,
  selectedDistrict: District | null,
  selectedVillage: Village | null,
  onSelectDistrict: (d: District) => void,
  onSelectVillage: (v: Village) => void,
  addressNote: string,
  onAddressChange: (val: string) => void
}> = ({ label, helper, icon, iconBg, selectedDistrict, selectedVillage, onSelectDistrict, onSelectVillage, addressNote, onAddressChange }) => {
  const [showDistricts, setShowDistricts] = useState(false);
  const [showVillages, setShowVillages] = useState(false);

  return (
    <div className="bg-white p-6 rounded-[2.5rem] card-shadow space-y-5">
      <div className="flex items-center gap-4 flex-row-reverse text-right">
        <div className={`${iconBg} p-3.5 rounded-2xl text-white shadow-lg`}>
          {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
        </div>
        <div className="flex-1">
          <h4 className="font-black text-slate-900 text-xl tracking-tight">{label}</h4>
          <p className="text-[10px] font-bold text-slate-400 mt-0.5">{helper}</p>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-3" dir="rtl">
        <div className="relative">
          <button onClick={() => { setShowDistricts(!showDistricts); setShowVillages(false); }} className="w-full bg-[#F8FAFC] p-4 rounded-2xl text-right flex justify-between items-center group transition-all text-xs">
             <ChevronDown className={`h-4 w-4 text-slate-300 transition-transform ${showDistricts ? 'rotate-180' : ''}`} />
             <div className="text-right">
                <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">المركز</p>
                <p className="text-xs font-black text-slate-800 truncate">{selectedDistrict?.name || "اختر المركز"}</p>
             </div>
          </button>
          {showDistricts && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl z-[500] max-h-48 overflow-y-auto no-scrollbar border border-slate-100 animate-in zoom-in">
               {MENOFIA_DATA.map(d => (
                 <button key={d.id} onClick={() => { onSelectDistrict(d); setShowDistricts(false); }} className="w-full p-4 text-right hover:bg-emerald-50 font-black text-xs border-b border-slate-50 last:border-none transition-colors">{d.name}</button>
               ))}
            </div>
          )}
        </div>
        <div className="relative">
          <button onClick={() => { if(selectedDistrict) setShowVillages(!showVillages); setShowDistricts(false); }} disabled={!selectedDistrict} className="w-full bg-[#F8FAFC] p-4 rounded-2xl text-right flex justify-between items-center disabled:opacity-50 transition-all text-xs">
             <ChevronDown className={`h-4 w-4 text-slate-300 transition-transform ${showVillages ? 'rotate-180' : ''}`} />
             <div className="text-right">
                <p className="text-[8px] font-black text-slate-400 uppercase mb-0.5">القرية</p>
                <p className="text-xs font-black text-slate-800 truncate">{selectedVillage?.name || "اختر القرية"}</p>
             </div>
          </button>
          {showVillages && selectedDistrict && (
            <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-2xl shadow-2xl z-[500] max-h-48 overflow-y-auto no-scrollbar border border-slate-100 animate-in zoom-in">
               {selectedDistrict.villages.map(v => (
                 <button key={v.id} onClick={() => { onSelectVillage(v); setShowVillages(false); }} className="w-full p-4 text-right hover:bg-emerald-50 font-black text-xs border-b border-slate-50 last:border-none transition-colors">{v.name}</button>
               ))}
            </div>
          )}
        </div>
      </div>
      <div className="relative">
        <Edit2 className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-300" />
        <input value={addressNote} onChange={e => onAddressChange(e.target.value)} placeholder="رقم المنزل، علامة مميزة (اختياري).." className="w-full bg-[#F8FAFC] p-5 pl-12 rounded-2xl text-xs font-bold outline-none text-right border-2 border-transparent focus:border-emerald-500/20 transition-all" />
      </div>
    </div>
  );
};

// --- Main Dashboard ---

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('FOOD');

  // Location States
  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [pickupNote, setPickupNote] = useState('');

  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNote, setDropoffNote] = useState('');

  // Food specific states
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [showCustomFoodOrder, setShowCustomFoodOrder] = useState(false);
  const [customFoodNotes, setCustomFoodNotes] = useState('');

  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('MOTORCYCLE');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Road distance states
  const [roadInfo, setRoadInfo] = useState<{ distance: number, duration: number, price: number } | null>(null);
  const [calculatingRoad, setCalculatingRoad] = useState(false);

  // Fix for Error: Cannot find name 'handleImageUpload'
  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      // compressImage logic is pre-imported
      const compressed = await compressImage(base64);
      setPrescriptionImg(compressed);
    };
    reader.readAsDataURL(file);
  };

  // دعم زر الرجوع للتبويبات والدردشة
  useEffect(() => {
    if (activeView !== 'NEW' || showChat) {
      window.history.pushState({ view: showChat ? 'chat' : activeView }, '');
      const handlePop = () => {
        if (showChat) setShowChat(false);
        else setActiveView('NEW');
      };
      window.addEventListener('popstate', handlePop);
      return () => window.removeEventListener('popstate', handlePop);
    }
  }, [activeView, showChat]);

  // مراقبة التغيرات لحساب تكلفة الطريق فوراً
  useEffect(() => {
    const calculateLivePrice = async () => {
      if (selectedCategory === 'TAXI' && pickupVillage && dropoffVillage) {
        setCalculatingRoad(true);
        const info = await getRoadDistance(
          pickupVillage.center.lat, pickupVillage.center.lng, 
          dropoffVillage.center.lat, dropoffVillage.center.lng
        );

        const vehicleMultiplier = DEFAULT_PRICING.multipliers[selectedVehicle] || 1.0;
        const calculatedPrice = Math.max(
          Math.round((DEFAULT_PRICING.basePrice + (info.distance * DEFAULT_PRICING.pricePerKm)) * vehicleMultiplier),
          DEFAULT_PRICING.minPrice
        );

        setRoadInfo({ ...info, price: calculatedPrice });
        setCalculatingRoad(false);
      } else {
        setRoadInfo(null);
      }
    };

    calculateLivePrice();
  }, [pickupVillage, dropoffVillage, selectedVehicle, selectedCategory]);

  useEffect(() => {
    const unsubRest = onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });

    return () => { unsubRest(); unsubOrders(); };
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const handleCreateOrder = async () => {
    if(!dropoffVillage) return alert('يرجى تحديد وجهة التوصيل أولاً');
    setIsSubmitting(true);
    try {
      let orderData: any = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH',
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        dropoffNotes: dropoffNote
      };

      if (selectedCategory === 'TAXI' && pickupVillage) {
        // نستخدم بيانات الطريق الفعلية إذا كانت متوفرة
        const finalDist = roadInfo?.distance || calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const finalPrice = roadInfo?.price || Math.max(Math.round(DEFAULT_PRICING.basePrice + (finalDist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);

        orderData = { ...orderData, 
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          pickupNotes: pickupNote, requestedVehicleType: selectedVehicle, distance: finalDist,
          price: finalPrice
        };
      } else if (selectedCategory === 'PHARMACY') {
        orderData = { ...orderData, notes: pharmacyNotes, prescriptionImage: prescriptionImg || undefined, requestedVehicleType: 'MOTORCYCLE', price: 25 };
      } else if (selectedCategory === 'FOOD' && showCustomFoodOrder) {
        orderData = { ...orderData, notes: customFoodNotes, pickupNotes: 'طلب طعام مخصص من مطعم غير مدرج', requestedVehicleType: 'MOTORCYCLE', price: 35 };
      }

      await addDoc(collection(db, "orders"), orderData);
      setShowCustomFoodOrder(false);
      setCustomFoodNotes('');
      setPharmacyNotes('');
    } catch (e) { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      // حساب مسافة الطريق للمطعم أيضاً لضمان الدقة
      const roadData = await getRoadDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (roadData.distance * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: roadData.distance, paymentMethod: 'CASH', foodItems: cart, 
        restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name,
        dropoffNotes: dropoffNote
      });
      setViewingRestaurant(null);
    } catch (e) { alert('فشل إرسال طلب الطعام'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId,
        driverName: offer.driverName,
        driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED,
        price: offer.price,
        driverRating: offer.driverRating,
        driverPhoto: offer.driverPhoto,
        acceptedAt: Date.now()
      });
    } catch (e) {
      alert('فشل قبول العرض');
    }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => window.history.back()} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => window.history.back()} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => window.history.back()} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => window.history.back()} />;

  return (
    <div className="rh-layout relative h-full w-full">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      {viewingRestaurant && (
        <RestaurantMenu 
          restaurant={viewingRestaurant} 
          onClose={() => setViewingRestaurant(null)} 
          onCheckout={handleCheckoutFood} 
        />
      )}

      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in">
