  const [pickupNote, setPickupNote] = useState('');

  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNote, setDropoffNote] = useState('');

  // Food specific states
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [showCustomFoodOrder, setShowCustomFoodOrder] = useState(false);
  const [customFoodNotes, setCustomFoodNotes] = useState('');

  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('MOTORCYCLE');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const adminWhatsApp = "201065019364";

  // Road distance states
  const [roadInfo, setRoadInfo] = useState<{ distance: number, duration: number, price: number } | null>(null);
  const [calculatingRoad, setCalculatingRoad] = useState(false);

  // Fix for Error: Cannot find name 'handleImageUpload'
  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64 = reader.result as string;
      // compressImage logic is pre-imported
      const compressed = await compressImage(base64);
      setPrescriptionImg(compressed);
    };
    reader.readAsDataURL(file);
  };

  // دعم زر الرجوع للتبويبات والدردشة
  useEffect(() => {
    if (activeView !== 'NEW' || showChat) {
      window.history.pushState({ view: showChat ? 'chat' : activeView }, '');
      const handlePop = () => {
        if (showChat) setShowChat(false);
        else setActiveView('NEW');
      };
      window.addEventListener('popstate', handlePop);
      return () => window.removeEventListener('popstate', handlePop);
    }
  }, [activeView, showChat]);

  // مراقبة التغيرات لحساب تكلفة الطريق فوراً
  useEffect(() => {
    const calculateLivePrice = async () => {
      if (selectedCategory === 'TAXI' && pickupVillage && dropoffVillage) {
        setCalculatingRoad(true);
        const info = await getRoadDistance(
          pickupVillage.center.lat, pickupVillage.center.lng, 
          dropoffVillage.center.lat, dropoffVillage.center.lng
        );

        const vehicleMultiplier = DEFAULT_PRICING.multipliers[selectedVehicle] || 1.0;
        const calculatedPrice = Math.max(
          Math.round((DEFAULT_PRICING.basePrice + (info.distance * DEFAULT_PRICING.pricePerKm)) * vehicleMultiplier),
          DEFAULT_PRICING.minPrice
        );

        setRoadInfo({ ...info, price: calculatedPrice });
        setCalculatingRoad(false);
      } else {
        setRoadInfo(null);
      }
    };

    calculateLivePrice();
  }, [pickupVillage, dropoffVillage, selectedVehicle, selectedCategory]);

  useEffect(() => {
    const unsubRest = onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });

    const unsubOrders = onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });

    return () => { unsubRest(); unsubOrders(); };
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const handleCreateOrder = async () => {
    if(!dropoffVillage) return alert('يرجى تحديد وجهة التوصيل أولاً');
    setIsSubmitting(true);
    try {
      let orderData: any = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH',
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        dropoffNotes: dropoffNote
      };

      let waMsg = `*📢 طلب جديد من وصلها*\n`;
      waMsg += `👤 *العميل:* ${user.name}\n`;
      waMsg += `📞 *الهاتف:* ${user.phone}\n`;
      waMsg += `📂 *النوع:* ${selectedCategory === 'TAXI' ? 'مشوار (تاكسي)' : selectedCategory === 'PHARMACY' ? 'صيدلية' : 'طعام مخصص'}\n`;

      if (selectedCategory === 'TAXI' && pickupVillage) {
        const finalDist = roadInfo?.distance || calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const finalPrice = roadInfo?.price || Math.max(Math.round(DEFAULT_PRICING.basePrice + (finalDist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);

        orderData = { ...orderData, 
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          pickupNotes: pickupNote, requestedVehicleType: selectedVehicle, distance: finalDist,
          price: finalPrice
        };

        waMsg += `📍 *من:* ${pickupVillage.name}\n`;
        waMsg += `🏁 *إلى:* ${dropoffVillage.name}\n`;
        waMsg += `💰 *التكلفة:* ${finalPrice} ج.م\n`;
        waMsg += `🛵 *المركبة:* ${selectedVehicle}\n`;
      } else if (selectedCategory === 'PHARMACY') {
        orderData = { ...orderData, notes: pharmacyNotes, prescriptionImage: prescriptionImg || undefined, requestedVehicleType: 'MOTORCYCLE', price: 25 };
        waMsg += `🏁 *التوصيل إلى:* ${dropoffVillage.name}\n`;
        waMsg += `📝 *الطلبات:* ${pharmacyNotes}\n`;
      } else if (selectedCategory === 'FOOD' && showCustomFoodOrder) {
        orderData = { ...orderData, notes: customFoodNotes, pickupNotes: 'طلب طعام مخصص من مطعم غير مدرج', requestedVehicleType: 'MOTORCYCLE', price: 35 };
        waMsg += `🏁 *التوصيل إلى:* ${dropoffVillage.name}\n`;
        waMsg += `🍔 *الطلب:* ${customFoodNotes}\n`;
      }

      await addDoc(collection(db, "orders"), orderData);

      // إرسال رسالة واتساب
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');

      setShowCustomFoodOrder(false);
      setCustomFoodNotes('');
      setPharmacyNotes('');
    } catch (e) { alert('خطأ في إرسال الطلب'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      const roadData = await getRoadDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (roadData.distance * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
      const totalPrice = deliveryPrice + foodTotal;

      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: totalPrice, distance: roadData.distance, paymentMethod: 'CASH', foodItems: cart, 
        restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name,
        dropoffNotes: dropoffNote
      });

      // إرسال رسالة واتساب للإدارة
      let waMsg = `*🍔 طلب طعام جديد من وصلها*\n`;
      waMsg += `👤 *العميل:* ${user.name}\n`;
      waMsg += `📞 *الهاتف:* ${user.phone}\n`;
      waMsg += `🏪 *المطعم:* ${viewingRestaurant.name}\n`;
      waMsg += `🏁 *التوصيل إلى:* ${dropoffVillage.name}\n`;
      waMsg += `💰 *الإجمالي:* ${totalPrice} ج.م\n`;
      waMsg += `🛒 *الأصناف:*\n`;
      cart.forEach(item => {
        waMsg += `- ${item.name} (الكمية: ${item.quantity})\n`;
      });

      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');

      setViewingRestaurant(null);
    } catch (e) { alert('فشل إرسال طلب الطعام'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId,
        driverName: offer.driverName,
        driverPhone: offer.driverPhone,
        status: OrderStatus.ACCEPTED,
        price: offer.price,
        driverRating: offer.driverRating,
        driverPhoto: offer.driverPhoto,
        acceptedAt: Date.now()
      });
    } catch (e) {
      alert('فشل قبول العرض');
    }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => window.history.back()} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => window.history.back()} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => window.history.back()} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => window.history.back()} />;

  return (
    <div className="rh-layout relative h-full w-full">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      {viewingRestaurant && (
        <RestaurantMenu 
          restaurant={viewingRestaurant} 
          onClose={() => setViewingRestaurant(null)} 
          onCheckout={handleCheckoutFood} 
        />
      )}

      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in">
           <MapContainer center={[30.556, 31.01]} zoom={13} zoomControl={false} className="w-full h-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
           </MapContainer>
        </div>
      )}

      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-10 space-y-10 max-xl mx-auto text-right">
          {!activeOrder ? (
            <>
              {/* Header */}
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-5xl font-black text-[#0F172A] tracking-tighter">وصـــلــهــا</h2>
                    <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest mt-1.5 opacity-80">توصيل ذكي لكل مراكز المنوفية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-[#EBFDF5] text-[#2D9469] rounded-[1.5rem] shadow-sm active:scale-90 transition-all border border-emerald-50"><Bot className="h-7 w-7" /></button>
              </div>

              {/* Category Icons */}
              <div className="flex justify-center gap-5">
                  {[
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> },
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> }
                  ].map(cat => (
                    <button 
                        key={cat.id} 
                        onClick={() => { setSelectedCategory(cat.id as OrderCategory); setShowCustomFoodOrder(false); }} 
                        className={`w-28 h-36 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 bg-white card-shadow category-btn ${selectedCategory === cat.id ? 'active' : 'opacity-40 grayscale-[0.5]'}`}
                    >
                       <div className={`p-4 rounded-full transition-colors ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>
                          {React.cloneElement(cat.icon as React.ReactElement, { className: "h-9 w-9" })}
                       </div>
                       <span className={`text-xs font-black tracking-tight ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-400'}`}>{cat.label}</span>
                    </button>
                  ))}
              </div>

              {/* Form Content */}
              <div className="space-y-8 animate-in slide-in-from-bottom duration-700 pb-20">

                {selectedCategory === 'FOOD' && (
                  <>
                    <div onClick={() => setShowCustomFoodOrder(!showCustomFoodOrder)} className="bg-[#0F172A] p-10 rounded-[3rem] text-white flex justify-between items-center shadow-2xl relative overflow-hidden group cursor-pointer active:scale-95 transition-all">
                       <div className="bg-[#10b981] p-5 rounded-[1.8rem] shadow-xl group-hover:scale-110 transition-transform"><Plus className="h-8 w-8" /></div>
                       <div className="text-right">
                          <h4 className="text-2xl font-black leading-tight">مطعمك مش موجود؟</h4>
                          <p className="text-[11px] font-bold text-emerald-400 mt-1 uppercase tracking-widest">اطلب من أي مطعم تريده في المنوفية</p>
                       </div>
                       <ChevronRight className={`h-6 w-6 text-white/20 transition-transform ${showCustomFoodOrder ? 'rotate-90' : 'rotate-180'}`} />
                    </div>

                    {showCustomFoodOrder ? (
                      <div className="bg-white p-8 rounded-[2.5rem] card-shadow space-y-6 animate-in zoom-in border-2 border-emerald-100">
                        <div className="space-y-4">
                           <div className="flex items-center gap-3 flex-row-reverse text-right">
                             <div className="bg-emerald-500 p-3 rounded-2xl text-white shadow-md"><Edit2 className="h-5 w-5" /></div>
                             <h5 className="text-xl font-black text-slate-800">تفاصيل الطلب المخصص</h5>
                           </div>
                           <textarea 
                             value={customFoodNotes} 
                             onChange={e => setCustomFoodNotes(e.target.value)} 
                             placeholder="اكتب اسم المطعم والوجبات المطلوبة بالتفصيل (مثل: 2 ساندوتش كفتة من مطعم البرنس)..." 
                             className="w-full bg-slate-50 border-none rounded-3xl p-6 font-bold text-sm outline-none text-right min-h-[160px] shadow-inner focus:bg-white transition-all" 
                           />
                        </div>
                      </div>
                    ) : (
                      <div className="grid grid-cols-1 gap-6">
                        <div className="flex justify-between items-center px-4">
                           <p className="text-xs font-black text-slate-400 uppercase tracking-[0.2em]">المطاعم القريبة منك</p>
                           <Store className="h-4 w-4 text-slate-300" />
                        </div>
                        {restaurants.length > 0 ? restaurants.map(rest => (
                          <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-7 rounded-[3rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-[0.98]">
                             <div className="flex items-center gap-5 flex-row-reverse text-right">
                                <div className="w-16 h-16 bg-slate-900 rounded-[1.5rem] flex items-center justify-center overflow-hidden border-2 border-white shadow-lg">
                                   {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="h-8 w-8 text-emerald-400" />}
                                </div>
                                <div>
                                   <h4 className="text-xl font-black text-slate-800 leading-tight group-hover:text-emerald-600 transition-colors">{rest.name}</h4>
                                   <p className="text-xs font-bold text-slate-400 mt-1 uppercase tracking-widest">{rest.category} • المنوفية</p>
                                </div>
                             </div>
                             <div className="bg-slate-50 p-4 rounded-2xl group-hover:bg-emerald-50 transition-colors">
                                <ChevronRight className="h-5 w-5 text-slate-300 rotate-180 group-hover:text-emerald-500" />
                             </div>
                          </div>
                        )) : (
                          <div className="py-20 text-center text-slate-300 font-black border-4 border-dashed border-slate-100 rounded-[3rem] bg-white/50">
                             <Loader2 className="animate-spin h-10 w-10 mx-auto mb-4" />
                             <p>جاري تحميل قائمة المطاعم...</p>
                          </div>
                        )}
                      </div>
                    )}
                  </>
                )}

                {selectedCategory === 'TAXI' && (
                  <LocationSelector label="نقطة الانطلاق" helper="موقع استلامك" icon={<MapPin />} iconBg="bg-[#10b981]" selectedDistrict={pickupDistrict} selectedVillage={pickupVillage} onSelectDistrict={setPickupDistrict} onSelectVillage={setPickupVillage} addressNote={pickupNote} onAddressChange={setPickupNote} />
                )}

                <LocationSelector 
                  label={selectedCategory === 'TAXI' ? "وجهة الوصول" : selectedCategory === 'PHARMACY' ? "مكان التوصيل" : "التوصيل إلى"} 
                  helper={selectedCategory === 'TAXI' ? "أين تذهب؟" : "أين ستستلم طلبك؟"}
                  icon={selectedCategory === 'TAXI' ? <CheckCircle2 /> : <MapPin />} 
                  iconBg={selectedCategory === 'TAXI' ? "bg-rose-500" : selectedCategory === 'PHARMACY' ? "bg-[#0085C7]" : "bg-rose-500"}
                  selectedDistrict={dropoffDistrict} selectedVillage={dropoffVillage}
                  onSelectDistrict={setDropoffDistrict} onSelectVillage={setDropoffVillage}
                  addressNote={dropoffNote} onAddressChange={setDropoffNote}
                />

                {selectedCategory === 'PHARMACY' && (
                  <div className="space-y-6">
                    <div className="bg-white p-1 rounded-[2.5rem] card-shadow">
                      <div className="bg-white border-2 border-blue-500/20 p-8 rounded-[2.5rem] relative">
                         <textarea value={pharmacyNotes} onChange={e => setPharmacyNotes(e.target.value)} placeholder="اكتب أسماء الأدوية المطلوبة هنا..." className="w-full min-h-[160px] outline-none font-bold text-lg text-right bg-transparent placeholder-slate-300 mb-4" />

                         {prescriptionImg ? (
                           <div className="relative w-full aspect-video rounded-3xl overflow-hidden border-4 border-white shadow-lg animate-in zoom-in">
                              <img src={prescriptionImg} className="w-full h-full object-cover" alt="Prescription" />
                              <button onClick={() => setPrescriptionImg(null)} className="absolute top-4 right-4 bg-rose-500 text-white p-2 rounded-full shadow-lg active:scale-75 transition-all">
                                 <X className="h-4 w-4" />
                              </button>
                           </div>
                         ) : (
                           <button 
                             onClick={() => fileInputRef.current?.click()}
                             className="w-full border-2 border-dashed border-blue-200 bg-blue-50/30 py-10 rounded-3xl flex flex-col items-center justify-center gap-3 text-blue-400 hover:bg-blue-50 hover:border-blue-300 transition-all active:scale-[0.98]"
                           >
                              <div className="bg-white p-4 rounded-2xl shadow-sm"><Camera className="h-8 w-8" /></div>
                              <p className="font-black text-xs uppercase tracking-widest">رفع صورة الروشته</p>
                           </button>
                         )}
                         <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />

                         <div className="absolute top-6 left-6 w-12 h-12 bg-[#0085C7] rounded-full flex items-center justify-center shadow-xl border-4 border-white"><Pill className="h-5 w-5 text-white" /></div>
                      </div>
                    </div>
                  </div>
                )}

                {selectedCategory === 'TAXI' && (
                  <div className="flex justify-center gap-4">
                    {[
                      { id: 'TOKTOK', label: 'توكتوك', icon: <Zap /> },
                      { id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike /> },
                      { id: 'CAR', label: 'سيارة', icon: <Car /> }
                    ].map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v.id as VehicleType)} className={`flex-1 py-8 rounded-[2.5rem] flex flex-col items-center gap-3 transition-all card-shadow ${selectedVehicle === v.id ? 'bg-white border-[4px] border-[#2D9469] text-[#2D9469] scale-105' : 'bg-white opacity-40 text-slate-300 grayscale'}`}>
                         {React.cloneElement(v.icon as React.ReactElement, { className: "h-8 w-8" })}
                         <span className="text-[11px] font-black uppercase tracking-widest">{v.label}</span>
                      </button>
                    ))}
                  </div>
                )}

                {/* عرض تفاصيل السعر المعتمد على الطريق */}
                {selectedCategory === 'TAXI' && pickupVillage && dropoffVillage && (
                   <PriceEstimateCard 
                     loading={calculatingRoad} 
                     distance={roadInfo?.distance || 0} 
                     duration={roadInfo?.duration || 0} 
                     price={roadInfo?.price || 0} 
                     vehicle={selectedVehicle}
                   />
                )}

                <button 
                  onClick={handleCreateOrder} 
                  disabled={isSubmitting || !dropoffVillage} 
                  className={`w-full py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all ${selectedCategory === 'PHARMACY' ? 'bg-[#0085C7] text-white shadow-blue-900/20' : 'bg-[#10b981] text-white shadow-emerald-900/20'}`}
                >
                   {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : <><FileText className="h-7 w-7" /> إرسال طلبك الآن</>}
                </button>
              </div>
            </>
          ) : (
            /* Order Tracking View */
            <div className="space-y-12 animate-reveal">
                {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="space-y-12 text-center py-10">
                    <div className="bg-white p-16 rounded-full card-shadow relative z-10 inline-block animate-pulse border-8 border-emerald-50"><Navigation2 className="h-24 w-24 text-emerald-600" /></div>
                    <div className="space-y-2">
                       <h2 className="text-4xl font-black text-slate-900 tracking-tighter">جاري جلب العروض...</h2>
                       <p className="text-slate-400 font-bold text-sm">نبحث لك عن أقرب كابتن متاح في المنوفية</p>
                    </div>
                    <div className="space-y-4 px-2">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-8 rounded-[3rem] card-shadow flex justify-between items-center border-2 border-emerald-50 hover:border-emerald-500 transition-all animate-in zoom-in">
                            <div className="text-center space-y-2">
                               <p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-black text-sm shadow-lg active:scale-90 transition-all">قبول</button>
                            </div>
                            <div className="flex items-center gap-5 flex-row-reverse text-right">
                               <div className="w-16 h-16 bg-slate-950 text-emerald-400 rounded-[1.5rem] flex items-center justify-center font-black text-2xl overflow-hidden border-2 border-white shadow-md">
                                 {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : (offer.driverName || 'ك')[0]}
                               </div>
                               <div>
