  const [showCustomFoodOrder, setShowCustomFoodOrder] = useState(false);
  const [customFoodNotes, setCustomFoodNotes] = useState('');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('MOTORCYCLE');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const adminWhatsApp = "201065019364";
  const [roadInfo, setRoadInfo] = useState<{ distance: number, duration: number, price: number } | null>(null);
  const [calculatingRoad, setCalculatingRoad] = useState(false);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = async () => {
      const compressed = await compressImage(reader.result as string);
      setPrescriptionImg(compressed);
    };
    reader.readAsDataURL(file);
  };

  useEffect(() => {
    const calculateLivePrice = async () => {
      if (selectedCategory === 'TAXI' && pickupVillage && dropoffVillage) {
        setCalculatingRoad(true);
        const info = await getRoadDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const mult = DEFAULT_PRICING.multipliers[selectedVehicle] || 1.0;
        const price = Math.max(Math.round((DEFAULT_PRICING.basePrice + (info.distance * DEFAULT_PRICING.pricePerKm)) * mult), DEFAULT_PRICING.minPrice);
        setRoadInfo({ ...info, price });
        setCalculatingRoad(false);
      } else setRoadInfo(null);
    };
    calculateLivePrice();
  }, [pickupVillage, dropoffVillage, selectedVehicle, selectedCategory]);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  const handleCreateOrder = async () => {
    if(!dropoffVillage) return alert('يرجى تحديد وجهة التوصيل');
    setIsSubmitting(true);
    try {
      let orderData: any = { customerId: user.id, customerPhone: user.phone, category: selectedCategory, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH', dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name }, dropoffNotes: dropoffNote };
      let waMsg = `*📢 طلب جديد من وصلها*\n👤 *العميل:* ${user.name}\n📞 *الهاتف:* ${user.phone}\n📂 *النوع:* ${selectedCategory === 'TAXI' ? 'مشوار (تاكسي)' : selectedCategory === 'PHARMACY' ? 'صيدلية' : 'طعام مخصص'}\n`;
      if (selectedCategory === 'TAXI' && pickupVillage) {
        const dist = roadInfo?.distance || 0;
        const price = roadInfo?.price || 20;
        orderData = { ...orderData, pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name }, pickupNotes: pickupNote, requestedVehicleType: selectedVehicle, distance: dist, price };
        waMsg += `📍 *من:* ${pickupVillage.name}\n🏁 *إلى:* ${dropoffVillage.name}\n💰 *التكلفة:* ${price} ج.م\n🛵 *المركبة:* ${selectedVehicle}`;
      } else if (selectedCategory === 'PHARMACY') {
        orderData = { ...orderData, notes: pharmacyNotes, prescriptionImage: prescriptionImg || undefined, requestedVehicleType: 'MOTORCYCLE', price: 25 };
        waMsg += `🏁 *التوصيل لـ:* ${dropoffVillage.name}\n📝 *الطلبات:* ${pharmacyNotes}${prescriptionImg ? '\n🖼️ *مرفق صورة روشتة بالطلب*' : ''}`;
      } else if (selectedCategory === 'FOOD' && showCustomFoodOrder) {
        orderData = { ...orderData, notes: customFoodNotes, pickupNotes: 'طلب طعام مخصص', requestedVehicleType: 'MOTORCYCLE', price: 35 };
        waMsg += `🏁 *التوصيل لـ:* ${dropoffVillage.name}\n🍔 *الوجبات:* ${customFoodNotes}`;
      }
      await addDoc(collection(db, "orders"), orderData);
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
      setPharmacyNotes(''); setCustomFoodNotes('');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
      const roadData = await getRoadDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const delivery = Math.max(Math.round(DEFAULT_PRICING.basePrice + (roadData.distance * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((a, c) => a + (c.price * c.quantity), 0);
      const totalPrice = delivery + foodTotal;
      await addDoc(collection(db, "orders"), { customerId: user.id, customerPhone: user.phone, category: 'FOOD', pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address }, dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name }, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE', price: totalPrice, distance: roadData.distance, paymentMethod: 'CASH', foodItems: cart, restaurantName: viewingRestaurant.name, dropoffNotes: dropoffNote });
      let waMsg = `*🍔 طلب طعام جديد*\n👤 *العميل:* ${user.name}\n📞 *الهاتف:* ${user.phone}\n🏪 *المطعم:* ${viewingRestaurant.name}\n🏁 *التوصيل لـ:* ${dropoffVillage.name}\n💰 *الإجمالي:* ${totalPrice} ج.م\n🛒 *الأصناف:*\n${cart.map(i => `- ${i.name} (x${i.quantity})`).join('\n')}`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
      setViewingRestaurant(null);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder) return;
    if (!window.confirm("هل تريد إلغاء الطلب نهائياً؟")) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED, cancelledAt: Date.now() });
      const cancelMsg = `*❌ تم إلغاء طلب من العميل*\n👤 *العميل:* ${user.name}\n📞 *الهاتف:* ${user.phone}\n🆔 *الطلب:* ${activeOrder.id.slice(-6)}`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(cancelMsg)}`, '_blank');
      alert('تم الإلغاء بنجاح');
    } catch (e) { alert('فشل الإلغاء'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout relative h-full w-full">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-10 space-y-10 max-xl mx-auto text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-5xl font-black text-[#0F172A] tracking-tighter">وصـــلــهــا</h2>
                    <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest mt-1.5 opacity-80">المنوفية • خدمة ذكية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-[#EBFDF5] text-[#2D9469] rounded-[1.5rem] shadow-sm active:scale-90 border border-emerald-50"><Bot className="h-7 w-7" /></button>
              </div>
              <div className="flex justify-center gap-5">
                  {[{ id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }, { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> }, { id: 'TAXI', label: 'مشوار', icon: <Bike /> }].map(cat => (
                    <button key={cat.id} onClick={() => { setSelectedCategory(cat.id as OrderCategory); setShowCustomFoodOrder(false); }} className={`w-28 h-36 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 bg-white card-shadow category-btn ${selectedCategory === cat.id ? 'active' : 'opacity-40grayscale'}`}>
                       <div className={`p-4 rounded-full transition-colors ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>{cat.icon}</div>
                       <span className={`text-xs font-black ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-400'}`}>{cat.label}</span>
                    </button>
                  ))}
              </div>
              <div className="space-y-8 pb-20">
                {selectedCategory === 'FOOD' && (
                  <div onClick={() => setShowCustomFoodOrder(!showCustomFoodOrder)} className="bg-[#0F172A] p-10 rounded-[3rem] text-white flex justify-between items-center shadow-2xl group cursor-pointer active:scale-95 transition-all">
                     <div className="bg-[#10b981] p-5 rounded-[1.8rem]"><Plus className="h-8 w-8" /></div>
                     <div className="text-right">
                        <h4 className="text-2xl font-black leading-tight">مطعمك مش موجود؟</h4>
                        <p className="text-[11px] font-bold text-emerald-400 mt-1 uppercase">اطلب أي وجبة من أي مكان في المنوفية</p>
                     </div>
                     <ChevronRight className={`h-6 w-6 text-white/20 transition-transform ${showCustomFoodOrder ? 'rotate-90' : 'rotate-180'}`} />
                  </div>
                )}
                {showCustomFoodOrder && selectedCategory === 'FOOD' ? (
                   <textarea value={customFoodNotes} onChange={e => setCustomFoodNotes(e.target.value)} placeholder="اكتب الوجبات واسم المطعم بالتفصيل..." className="w-full bg-white border-2 border-emerald-100 rounded-3xl p-6 font-bold text-sm min-h-[160px] shadow-sm" />
                ) : selectedCategory === 'FOOD' && (
                   <div className="grid gap-6">
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-7 rounded-[3rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 cursor-pointer transition-all">
                           <div className="flex items-center gap-5 flex-row-reverse text-right">
                              <div className="w-16 h-16 bg-slate-900 rounded-[1.5rem] overflow-hidden">{rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-emerald-400" />}</div>
                              <div><h4 className="text-xl font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-xs font-bold text-slate-400 uppercase">{rest.category}</p></div>
                           </div>
                           <ChevronRight className="h-5 w-5 text-slate-300 rotate-180" />
                        </div>
                      ))}
                   </div>
                )}
                <button onClick={handleCreateOrder} disabled={isSubmitting || !dropoffVillage} className={`w-full py-8 rounded-[2.5rem] font-black text-2xl shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all ${selectedCategory === 'PHARMACY' ? 'bg-[#0085C7] text-white' : 'bg-[#10b981] text-white'}`}>
                   {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : <><FileText className="h-7 w-7" /> إرسال طلبك الآن</>}
                </button>
              </div>
            </>
          ) : (
            <div className="space-y-12 animate-reveal">
                {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="space-y-12 text-center py-10">
                    <div className="bg-white p-16 rounded-full card-shadow inline-block animate-pulse border-8 border-emerald-50"><Navigation2 className="h-24 w-24 text-emerald-600" /></div>
                    <div className="space-y-2">
                       <h2 className="text-4xl font-black text-slate-900 tracking-tighter">جاري جلب العروض...</h2>
                       <p className="text-slate-400 font-bold text-sm">نبحث لك عن أقرب كابتن متاح في المنوفية</p>
                    </div>
                    <div className="space-y-4 px-2">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-8 rounded-[3rem] card-shadow flex justify-between items-center border-2 border-emerald-50 animate-in zoom-in">
                            <div className="text-center space-y-2"><p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p><button onClick={async () => await updateDoc(doc(db, "orders", activeOrder.id), { driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, status: OrderStatus.ACCEPTED, price: offer.price, driverRating: offer.driverRating, driverPhoto: offer.driverPhoto, acceptedAt: Date.now() })} className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-black text-sm shadow-lg active:scale-90 transition-all">قبول</button></div>
                            <div className="flex items-center gap-5 flex-row-reverse text-right">
                               <div className="w-16 h-16 bg-slate-950 text-emerald-400 rounded-[1.5rem] flex items-center justify-center overflow-hidden border-2 border-white shadow-md">{offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : (offer.driverName || 'ك')[0]}</div>
                               <div><p className="font-black text-slate-900 text-xl mb-2">{offer.driverName}</p><div className="flex items-center gap-2 text-amber-500 font-black text-xs bg-amber-50 px-4 py-1.5 rounded-full inline-flex">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={handleCancelOrder} className="text-rose-500 font-black text-xs uppercase tracking-widest hover:underline">إلغاء الطلب</button>
                 </div>
                ) : activeOrder.status === OrderStatus.DELIVERED ? (
                  <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                     <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto animate-bounce" />
                     <h2 className="text-3xl font-black text-slate-950">وصلت بالسلامة!</h2>
                     <button onClick={async () => await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now() })} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl">تأكيد <ThumbsUp className="h-8 w-8 inline mr-2" /></button>
                  </div>
                ) : (
                  <div className="space-y-12 pb-32">
                     <div className="bg-[#2D9469] p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                        <div className="text-right">
                           <p className="text-xs font-black opacity-60 uppercase mb-2">تتبع الكابتن</p>
                           <h3 className="text-3xl font-black leading-none tracking-tighter">{activeOrder.status === OrderStatus.PICKED_UP ? 'جاري التوصيل' : 'الكابتن قادم إليك'}</h3>
                        </div>
                        <button onClick={() => setActiveView('MAP')} className="bg-white/20 p-5 rounded-full animate-bounce shadow-inner border border-white/10"><Navigation className="h-8 w-8" /></button>
                     </div>
                     <div className="flex flex-col items-center gap-8">
                        <div className="w-44 h-44 bg-slate-100 rounded-[3.5rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden relative">
                           {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : (activeOrder.driverName || 'ك')[0]}
                        </div>
                        <div className="text-center"><h4 className="text-4xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4><span className="bg-emerald-50 text-emerald-600 px-8 py-3 rounded-full inline-block font-black text-xs uppercase tracking-widest mt-3">كابتن معتمد في المنوفية</span></div>
                     </div>
                     <div className="grid grid-cols-2 gap-5">
                        <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-5 rounded-3xl font-black text-sm flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-5 w-5" /> اتصال</a>
                        <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-3xl font-black text-sm flex items-center justify-center gap-3 active:scale-95 transition-all"><MessageCircle className="h-5 w-5" /> دردشة</button>
                     </div>
                     {activeOrder.status === OrderStatus.ACCEPTED && <button onClick={handleCancelOrder} className="w-full py-4 text-rose-500 font-black text-xs uppercase tracking-widest flex items-center justify-center gap-2 hover:bg-rose-50 rounded-2xl"><AlertTriangle className="h-4 w-4" /> إلغاء الطلب بالكامل</button>}
                  </div>
                )}
            </div>
          )}
        </div>
      </div>
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3.5rem]">
         {[{id: 'NEW', icon: <Plus className="h-6 w-6" />, label: 'طلب جديد'}, {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'}, {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'نشاطي'}, {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-[#EBFDF5] shadow-inner scale-110' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, User as UserIcon, Home, 
  ShieldAlert, Bot, Zap, Car, Map as MapIcon,
  AlertTriangle, ExternalLink
} from 'lucide-react';

// React Leaflet
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc, getDoc, deleteField
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

const createDriverIcon = (type: string) => {
  let emoji = '🛵';
  if (type === 'CAR') emoji = '🚗';
  if (type === 'TOKTOK') emoji = '🛺';
  return L.divIcon({ html: `<div class="bg-white p-2 rounded-full shadow-2xl border-4 border-emerald-500 animate-pulse text-xl flex items-center justify-center">${emoji}</div>`, className: 'custom-driver-icon', iconSize: [45, 45], iconAnchor: [22, 22] });
};

const pickupIcon = L.divIcon({ html: `<div class="bg-white p-2 rounded-full shadow-lg border-4 border-rose-500 text-lg flex items-center justify-center">📍</div>`, className: 'pickup-icon', iconSize: [40, 40], iconAnchor: [20, 20] });

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);
  const adminWhatsApp = "201065019364";
  const [currentLocation, setCurrentLocation] = useState({ lat: 30.556, lng: 31.008 });
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (isOnline && "geolocation" in navigator) {
      watchId.current = navigator.geolocation.watchPosition((pos) => {
        const { latitude, longitude } = pos.coords;
        setCurrentLocation({ lat: latitude, lng: longitude });
        updateDoc(doc(db, "users", user.id), { location: { lat: latitude, lng: longitude, updatedAt: Date.now() } });
      }, null, { enableHighAccuracy: true });
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snap) => setAvailableOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [isOnline, user.id, user.status]);

  const handleRejectOrder = async () => {
    if (!activeOrder) return;
    if (!window.confirm("هل تريد الاعتذار عن المشوار؟ سيتم إبلاغ الإدارة فوراً.")) return;
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.WAITING_FOR_OFFERS, driverId: null, driverName: null, driverPhone: null, acceptedAt: null });
