  if (user.status !== 'APPROVED') return <div className="p-12 text-center font-black space-y-6"><ShieldAlert className="h-20 w-20 mx-auto text-emerald-600 animate-bounce" /><h2 className="text-3xl tracking-tighter">حسابك بانتظار التفعيل</h2><button onClick={() => window.open('https://wa.me/201065019364')} className="w-full bg-[#25D366] text-white py-6 rounded-[2rem] font-black shadow-xl">تواصل عبر واتساب</button></div>;
  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout relative">
      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in duration-500">
           <MapContainer center={[currentLocation.lat, currentLocation.lng]} zoom={14} zoomControl={false} className="w-full h-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
              <Marker position={[currentLocation.lat, currentLocation.lng]} icon={createDriverIcon(user.vehicleType || 'TOKTOK')}><Popup>أنت هنا</Popup></Marker>
              {activeOrder && <Marker position={[activeOrder.pickup.lat, activeOrder.pickup.lng]} icon={pickupIcon}><Popup>نقطة الاستلام</Popup></Marker>}
           </MapContainer>
        </div>
      )}
      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-12 space-y-8 max-w-2xl mx-auto text-right">
            <div className={`p-8 md:p-10 rounded-[3rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div><h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'نشط الآن' : 'متوقف'}</h2><p className="text-[10px] font-black opacity-60 mt-1 uppercase">كباتن المنوفية</p></div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2rem] shadow-2xl active:scale-90 transition-all ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power className="h-10 w-10" /></button>
            </div>
            {activeOrder ? (
               <div className="bg-white rounded-[4rem] shadow-2xl border-t-8 border-t-emerald-500 p-8 space-y-8 animate-reveal">
                  <div className="flex justify-between items-center"><span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase tracking-widest">{activeOrder.status}</span><p className="text-5xl font-black text-slate-950">{activeOrder.price} <span className="text-xs">ج.م</span></p></div>
                  <div className="space-y-6">
                     <div className="flex gap-4 items-start flex-row-reverse text-right">
                        <div className="bg-slate-50 p-4 rounded-2xl text-emerald-600 shadow-sm shrink-0"><MapPin className="h-6 w-6" /></div>
                        <div className="flex-1"><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">مسار الرحلة</p><p className="font-black text-lg text-slate-900 leading-tight">{activeOrder.pickup?.villageName} ← {activeOrder.dropoff?.villageName}</p></div>
                     </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4 pt-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-5 rounded-[1.8rem] font-black text-sm flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-5 w-5" /> اتصال</a>
                     <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-[1.8rem] font-black text-sm flex items-center justify-center gap-3 active:scale-95 transition-all relative"><MessageCircle className="h-5 w-5" /> دردشة</button>
                     <button onClick={() => setActiveView('MAP')} className="col-span-2 bg-emerald-50 text-emerald-600 py-4 rounded-[1.5rem] font-black text-xs flex items-center justify-center gap-2"><MapIcon className="h-4 w-4" /> عرض الخريطة</button>
                     <button onClick={async () => { setIsSubmitting(true); try { const status = activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED; await updateDoc(doc(db, "orders", activeOrder.id), { status, deliveredAt: status === OrderStatus.DELIVERED ? Date.now() : undefined }); } catch(e){} finally{setIsSubmitting(false);} }} disabled={isSubmitting} className="col-span-2 bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-lg shadow-2xl active:scale-95 transition-all">{isSubmitting ? <Loader2 className="h-7 w-7 animate-spin mx-auto" /> : activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تأكيد التوصيل'}</button>
                     {activeOrder.status === OrderStatus.ACCEPTED && <button onClick={handleRejectOrder} disabled={isSubmitting} className="col-span-2 py-3 text-rose-500 font-black text-xs uppercase flex items-center justify-center gap-2 hover:bg-rose-50 rounded-2xl transition-all"><AlertTriangle className="h-4 w-4" /> اعتذار عن المشوار</button>}
                     <button onClick={contactSupport} className="col-span-2 py-3 text-emerald-600 font-black text-xs uppercase flex items-center justify-center gap-2 border-2 border-emerald-50 rounded-2xl active:scale-95 transition-all"><ExternalLink className="h-4 w-4" /> تواصل مع الإدارة (واتساب)</button>
                  </div>
               </div>
            ) : (
               <div className="space-y-6 animate-reveal">
                  <h3 className="text-xs font-black text-slate-400 uppercase tracking-widest text-right px-4">مشاوير بانتظارك ({availableOrders.length})</h3>
                  {availableOrders.map(o => (
                     <div key={o.id} className="bg-white p-8 rounded-[3.5rem] border-2 border-slate-50 shadow-xl space-y-6 animate-reveal">
                        {showOfferInput === o.id ? (
                           <div className="space-y-6 animate-in zoom-in text-center">
                              <h4 className="text-xl font-black">تقديم عرض سعر</h4>
                              <input autoFocus type="number" value={offerPrice} onChange={e => setOfferPrice(e.target.value)} placeholder={o.price.toString()} className="w-full bg-slate-50 border-none rounded-3xl p-8 text-5xl font-black text-center outline-none" />
                              <div className="flex gap-4"><button onClick={() => setShowOfferInput(null)} className="flex-1 py-6 rounded-2xl font-black text-slate-400">إلغاء</button><button onClick={async () => { if(!parseFloat(offerPrice) || isSubmitting) return; setIsSubmitting(true); try { const uSnap = await getDoc(doc(db, "users", user.id)); const rating = uSnap.data()?.rating || 5.0; await addDoc(collection(db, "offers"), { orderId: o.id, driverId: user.id, driverName: user.name, driverPhone: user.phone, driverRating: rating, vehicleType: user.vehicleType || 'TOKTOK', price: parseFloat(offerPrice), createdAt: Date.now() }); setShowOfferInput(null); setOfferPrice(''); } catch(e){} finally{setIsSubmitting(false);} }} className="flex-[2] bg-emerald-600 text-white py-6 rounded-2xl font-black shadow-xl">إرسال العرض</button></div>
                           </div>
                        ) : (
                           <>
                              <div className="flex justify-between items-start text-right">
                                 <div className="space-y-2"><p className="text-2xl font-black text-slate-950">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p><p className="text-[10px] font-black text-emerald-600 bg-emerald-50 inline-block px-4 py-1.5 rounded-full">{o.requestedVehicleType}</p></div>
                                 <div className="bg-slate-950 text-emerald-400 p-6 rounded-[2.2rem] font-black text-3xl shrink-0">{o.price}</div>
                              </div>
                              <button onClick={() => { setShowOfferInput(o.id); setOfferPrice(o.price.toString()); }} className="w-full bg-slate-950 text-white py-6 rounded-[2.5rem] font-black text-xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4"><Zap className="h-6 w-6 text-emerald-400" /> تقديم عرض</button>
                           </>
                        )}
                     </div>
                  ))}
               </div>
            )}
        </div>
      </div>
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3rem]">
         {[{id: 'HOME', icon: <Home className="h-6 w-6" />, label: 'الرئيسية'}, {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'}, {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'سجلي'}, {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeView === tab.id ? 'text-emerald-600' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl transition-all ${activeView === tab.id ? 'bg-emerald-50 shadow-inner scale-110' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

