           <div className="flex gap-2 bg-slate-50 p-2 rounded-[2rem] md:rounded-[2.5rem] shadow-inner overflow-x-auto no-scrollbar w-full lg:w-auto">
              {[{ id: 'LIVE', label: 'النشاط', icon: <Zap className="h-4 w-4" />, count: liveOrders.length }, { id: 'DRIVERS', label: 'الكباتن', icon: <Bike className="h-4 w-4" />, count: drivers.filter(d => d.status === 'APPROVED').length }, { id: 'HISTORY', label: 'السجل', icon: <Clock className="h-4 w-4" /> }].map(tab => (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-8 py-4 md:px-10 md:py-5 rounded-[1.5rem] md:rounded-[1.8rem] text-[10px] md:text-[11px] font-black transition-all flex items-center gap-2 md:gap-3 whitespace-nowrap ${activeTab === tab.id ? 'bg-slate-950 text-white shadow-2xl' : 'text-slate-400 hover:text-slate-950'}`}>
                  {tab.icon} {tab.label}
                  {tab.count !== undefined && <span className={`px-2 py-0.5 rounded-full text-[8px] ${activeTab === tab.id ? 'bg-emerald-500 text-white' : 'bg-slate-200 text-slate-400'}`}>{tab.count}</span>}
