// --- Main Dashboard ---

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('FOOD');
  const [pickupDistrict, setPickupDistrict] = useState<District | null>(null);
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [pickupNote, setPickupNote] = useState('');
  const [dropoffDistrict, setDropoffDistrict] = useState<District | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [dropoffNote, setDropoffNote] = useState('');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [showCustomFoodOrder, setShowCustomFoodOrder] = useState(false);
  const [customFoodNotes, setCustomFoodNotes] = useState('');
  const [selectedVehicle, setSelectedVehicle] = useState<VehicleType>('MOTORCYCLE');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [pharmacyNotes, setPharmacyNotes] = useState('');
  const [prescriptionImg, setPrescriptionImg] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const adminWhatsApp = "201065019364";
  const [roadInfo, setRoadInfo] = useState<{ distance: number, duration: number, price: number } | null>(null);
  const [calculatingRoad, setCalculatingRoad] = useState(false);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onloadend = async () => {
      const compressed = await compressImage(reader.result as string);
      setPrescriptionImg(compressed);
    };
    reader.readAsDataURL(file);
  };

  useEffect(() => {
    const calculateLivePrice = async () => {
      if (selectedCategory === 'TAXI' && pickupVillage && dropoffVillage) {
        setCalculatingRoad(true);
        const info = await getRoadDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const mult = DEFAULT_PRICING.multipliers[selectedVehicle] || 1.0;
        const price = Math.max(Math.round((DEFAULT_PRICING.basePrice + (info.distance * DEFAULT_PRICING.pricePerKm)) * mult), DEFAULT_PRICING.minPrice);
        setRoadInfo({ ...info, price });
        setCalculatingRoad(false);
      } else setRoadInfo(null);
    };
    calculateLivePrice();
  }, [pickupVillage, dropoffVillage, selectedVehicle, selectedCategory]);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]));
    }
  }, [activeOrder]);

  const handleCreateOrder = async () => {
    if(!dropoffVillage) return alert('يرجى تحديد وجهة التوصيل');
    setIsSubmitting(true);
    try {
      let orderData: any = { customerId: user.id, customerPhone: user.phone, category: selectedCategory, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH', dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name }, dropoffNotes: dropoffNote };
      let waMsg = `*📢 طلب جديد من وصلها*\n👤 *العميل:* ${user.name}\n📞 *الهاتف:* ${user.phone}\n📂 *النوع:* ${selectedCategory === 'TAXI' ? 'مشوار (تاكسي)' : selectedCategory === 'PHARMACY' ? 'صيدلية' : 'طعام مخصص'}\n`;
      if (selectedCategory === 'TAXI' && pickupVillage) {
        const dist = roadInfo?.distance || 0;
        const price = roadInfo?.price || 20;
        orderData = { ...orderData, pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name }, pickupNotes: pickupNote, requestedVehicleType: selectedVehicle, distance: dist, price };
        waMsg += `📍 *من:* ${pickupVillage.name}\n🏁 *إلى:* ${dropoffVillage.name}\n💰 *التكلفة:* ${price} ج.م\n🛵 *المركبة:* ${selectedVehicle}`;
      } else if (selectedCategory === 'PHARMACY') {
        orderData = { ...orderData, notes: pharmacyNotes, prescriptionImage: prescriptionImg || undefined, requestedVehicleType: 'MOTORCYCLE', price: 25 };
        waMsg += `🏁 *التوصيل لـ:* ${dropoffVillage.name}\n📝 *الطلبات:* ${pharmacyNotes}${prescriptionImg ? '\n🖼️ *مرفق صورة روشتة بالطلب*' : ''}`;
      } else if (selectedCategory === 'FOOD' && showCustomFoodOrder) {
        orderData = { ...orderData, notes: customFoodNotes, pickupNotes: 'طلب طعام مخصص', requestedVehicleType: 'MOTORCYCLE', price: 35 };
        waMsg += `🏁 *التوصيل لـ:* ${dropoffVillage.name}\n🍔 *الوجبات:* ${customFoodNotes}`;
      }
      await addDoc(collection(db, "orders"), orderData);
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
      setPharmacyNotes(''); setCustomFoodNotes('');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[]) => {
    if (!viewingRestaurant || !dropoffVillage) return;
    setIsSubmitting(true);
    try {
      const roadData = await getRoadDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const delivery = Math.max(Math.round(DEFAULT_PRICING.basePrice + (roadData.distance * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((a, c) => a + (c.price * c.quantity), 0);
      const totalPrice = delivery + foodTotal;
      await addDoc(collection(db, "orders"), { customerId: user.id, customerPhone: user.phone, category: 'FOOD', pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address }, dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name }, status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE', price: totalPrice, distance: roadData.distance, paymentMethod: 'CASH', foodItems: cart, restaurantName: viewingRestaurant.name, dropoffNotes: dropoffNote });
      let waMsg = `*🍔 طلب طعام جديد*\n👤 *العميل:* ${user.name}\n📞 *الهاتف:* ${user.phone}\n🏪 *المطعم:* ${viewingRestaurant.name}\n🏁 *التوصيل لـ:* ${dropoffVillage.name}\n💰 *الإجمالي:* ${totalPrice} ج.م\n🛒 *الأصناف:*\n${cart.map(i => `- ${i.name} (x${i.quantity})`).join('\n')}`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
      setViewingRestaurant(null);
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder) return;
    if (!window.confirm("هل تريد إلغاء الطلب نهائياً؟")) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED, cancelledAt: Date.now() });
      const cancelMsg = `*❌ تم إلغاء طلب من العميل*\n👤 *العميل:* ${user.name}\n📞 *الهاتف:* ${user.phone}\n🆔 *الطلب:* ${activeOrder.id.slice(-6)}`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(cancelMsg)}`, '_blank');
      alert('تم الإلغاء بنجاح');
    } catch (e) { alert('فشل الإلغاء'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout relative h-full w-full">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-10 space-y-10 max-xl mx-auto text-right">
          {!activeOrder ? (
            <>
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-5xl font-black text-[#0F172A] tracking-tighter">وصـــلــهــا</h2>
                    <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest mt-1.5 opacity-80">المنوفية • خدمة ذكية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-[#EBFDF5] text-[#2D9469] rounded-[1.5rem] shadow-sm active:scale-90 border border-emerald-50"><Bot className="h-7 w-7" /></button>
              </div>
              <div className="flex justify-center gap-5">
                  {[{ id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }, { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> }, { id: 'TAXI', label: 'مشوار', icon: <Bike /> }].map(cat => (
