      </div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-white border-2 border-slate-100 p-5 rounded-[2.2rem] flex items-center justify-between cursor-pointer hover:border-emerald-200 transition-all shadow-sm">
        <ChevronDown className={`h-5 w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-4 flex-row-reverse text-right">
          <span className={`text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر القرية"}</span>
          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl`}>
            {React.cloneElement(icon as React.ReactElement, { className: "h-6 w-6" })}
          </div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute left-6 right-6 mt-2 bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 z-[1000] max-h-[300px] overflow-hidden flex flex-col animate-in zoom-in">
          <input className="p-5 border-b border-slate-50 font-black text-sm outline-none text-right" placeholder="ابحث عن قريتك..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} dir="rtl" />
          <div className="flex-1 overflow-y-auto no-scrollbar p-3">
             {filtered.map(v => (
               <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-4 hover:bg-emerald-50 rounded-2xl flex justify-between items-center flex-row-reverse text-right font-bold text-slate-700">
                  {v.name}
                  {selectedVillage?.id === v.id && <Check className="h-4 w-4 text-emerald-500" />}
               </button>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

// --- Main Dashboard ---

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);
  const [driverLocation, setDriverLocation] = useState<{ lat: number, lng: number } | null>(null);

  const adminWhatsApp = "201065019364";

  // متابعة حالة الطلبات النشطة
  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      const current = all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
      setActiveOrder(current || null);
    });
  }, [user.id]);

  // متابعة العروض للطلب الجديد
  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  // متابعة موقع الكابتن لحظياً عند قبول الطلب
  useEffect(() => {
    if (activeOrder?.driverId && [OrderStatus.ACCEPTED, OrderStatus.PICKED_UP].includes(activeOrder.status)) {
      return onSnapshot(doc(db, "users", activeOrder.driverId), (docSnap) => {
        const data = docSnap.data();
        if (data?.location) {
          setDriverLocation({ lat: data.location.lat, lng: data.location.lng });
        }
      });
    } else {
      setDriverLocation(null);
    }
  }, [activeOrder]);

  const handleCreateOrder = async () => {
    if(!dropoffVillage) return alert('يرجى تحديد وجهة التوصيل');
    setIsSubmitting(true);
    try {
      let orderData: any = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH',
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name }
      };

      if (selectedCategory === 'TAXI' && pickupVillage) {
        const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const price = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
        orderData = { ...orderData, pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name }, distance: dist, price, requestedVehicleType: 'TOKTOK' };
      }

      await addDoc(collection(db, "orders"), orderData);

      const waMsg = `*📢 طلب جديد من وصلها*\n👤 *العميل:* ${user.name}\n📂 *النوع:* ${selectedCategory}\n🏁 *الوجهة:* ${dropoffVillage.name}`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
    } catch (e) { alert('خطأ في الطلب'); } finally { setIsSubmitting(false); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder) return;
    if (!window.confirm("هل تريد إلغاء الطلب؟")) return;
    await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED, cancelledAt: Date.now() });
    alert('تم إلغاء الطلب');
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout relative h-full w-full">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={() => {}} />}

      {/* خريطة التتبع */}
      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in">
           <div className="absolute top-6 left-6 z-[1000] flex flex-col gap-3">
              <button onClick={() => setActiveView('NEW')} className="bg-slate-900 text-white p-4 rounded-2xl shadow-2xl flex items-center gap-2 font-black text-xs active:scale-90 transition-all border border-white/10">
                 <ArrowRight className="h-5 w-5" /> رجوع للتتبع
              </button>
           </div>

           <MapContainer center={driverLocation ? [driverLocation.lat, driverLocation.lng] : [30.298, 30.975]} zoom={15} zoomControl={false} className="w-full h-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />

              {/* موقع الكابتن */}
              {driverLocation && (
                <Marker position={[driverLocation.lat, driverLocation.lng]} icon={createDriverIcon(activeOrder?.requestedVehicleType || 'TOKTOK')}>
                   <Popup><div className="text-right font-black">الكابتن {activeOrder?.driverName}</div></Popup>
                   <RecenterMap coords={[driverLocation.lat, driverLocation.lng]} />
                </Marker>
              )}

              {/* نقاط الطلب */}
              {activeOrder?.pickup?.lat && (
                <Marker position={[activeOrder.pickup.lat, activeOrder.pickup.lng]} icon={pickupIcon}>
                   <Popup><div className="text-right font-bold">نقطة الاستلام</div></Popup>
                </Marker>
              )}
              {activeOrder?.dropoff?.lat && (
                <Marker position={[activeOrder.dropoff.lat, activeOrder.dropoff.lng]} icon={dropoffIcon}>
                   <Popup><div className="text-right font-bold">وجهة الوصول</div></Popup>
                </Marker>
              )}
           </MapContainer>

           <div className="absolute bottom-28 left-6 right-6 z-[1000]">
              <div className="bg-white/90 backdrop-blur-xl p-6 rounded-[2.5rem] shadow-2xl border border-white flex justify-between items-center flex-row-reverse animate-reveal">
                 <div className="text-right">
                    <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest mb-1">حالة الكابتن</p>
