                 <div className="bg-emerald-500 p-4 rounded-2xl text-white shadow-lg animate-float">
                    <Navigation className="h-6 w-6" />
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* الواجهة الرئيسية */}
