                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`w-28 h-36 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 bg-white card-shadow category-btn ${selectedCategory === cat.id ? 'active' : 'opacity-40grayscale'}`}>
                       <div className={`p-4 rounded-full transition-colors ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>{cat.icon}</div>
