                         <div key={offer.id} className="bg-white p-8 rounded-[3rem] card-shadow flex justify-between items-center border-2 border-emerald-50 animate-in zoom-in">
                            <div className="text-center space-y-2">
                               <p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p>
                               <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, status: OrderStatus.ACCEPTED, price: offer.price, driverPhoto: offer.driverPhoto, acceptedAt: Date.now() })} className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-black text-sm shadow-lg">قبول</button>
                            </div>
                            <div className="flex items-center gap-4 flex-row-reverse text-right">
                               <div className="w-16 h-16 bg-slate-950 text-emerald-400 rounded-2xl flex items-center justify-center font-black overflow-hidden shadow-md">
