                               </div>
                               <div><p className="font-black text-slate-900 text-xl">{offer.driverName}</p><div className="flex items-center gap-2 text-amber-500 font-black text-xs bg-amber-50 px-4 py-1.5 rounded-full inline-flex">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={handleCancelOrder} className="text-rose-500 font-black text-xs uppercase hover:underline">إلغاء الطلب</button>
                 </div>
                ) : activeOrder.status === OrderStatus.DELIVERED ? (
                  <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                     <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto animate-bounce" />
                     <h2 className="text-3xl font-black text-slate-950">وصلت بالسلامة!</h2>
                     <button onClick={async () => await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now() })} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl">تأكيد <ThumbsUp className="h-8 w-8 inline mr-2" /></button>
                  </div>
                ) : (
                  <div className="space-y-12 pb-32">
                     <div className="bg-[#2D9469] p-10 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                        <div className="text-right">
                           <p className="text-xs font-black opacity-60 uppercase mb-2">تتبع الكابتن</p>
                           <h3 className="text-3xl font-black leading-none tracking-tighter">{activeOrder.status === OrderStatus.PICKED_UP ? 'جاري التوصيل' : 'الكابتن قادم إليك'}</h3>
                        </div>
                        <button onClick={() => setActiveView('MAP')} className="bg-white/20 p-5 rounded-full animate-glow shadow-inner border border-white/10">
                           <LocateFixed className="h-8 w-8" />
                        </button>
                     </div>

                     <div className="flex flex-col items-center gap-8">
                        <div className="w-44 h-44 bg-slate-100 rounded-[3.5rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden relative">
                           {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                        </div>
                        <div className="text-center">
                           <h4 className="text-4xl font-black text-slate-950 tracking-tighter">{activeOrder.driverName}</h4>
                           <span className="bg-emerald-50 text-emerald-600 px-8 py-3 rounded-full inline-block font-black text-xs uppercase mt-3">كابتن معتمد</span>
                        </div>
                     </div>

                     <div className="grid grid-cols-2 gap-5">
                        <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-5 rounded-3xl font-black text-sm flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-5 w-5" /> اتصال</a>
                        <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-5 rounded-3xl font-black text-sm flex items-center justify-center gap-3 active:scale-95 transition-all"><MessageCircle className="h-5 w-5" /> دردشة</button>
                     </div>

                     <button onClick={() => setActiveView('MAP')} className="w-full bg-emerald-50 text-emerald-600 py-6 rounded-3xl font-black text-lg flex items-center justify-center gap-3 shadow-sm border-2 border-emerald-100 animate-glow">
                        <MapIcon className="h-6 w-6" /> فتح خريطة التتبع المباشر
                     </button>

                     {activeOrder.status === OrderStatus.ACCEPTED && (
                        <button onClick={handleCancelOrder} className="w-full py-4 text-rose-500 font-black text-xs uppercase flex items-center justify-center gap-2 hover:bg-rose-50 rounded-2xl transition-all">
                           <AlertTriangle className="h-4 w-4" /> إلغاء الطلب
                        </button>
                     )}
                  </div>
                )}
            </div>
          )}
        </div>
      </div>

      {/* Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3.5rem]">
         {[
           {id: 'NEW', icon: <Plus className="h-6 w-6" />, label: 'طلب جديد'},
           {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-[#EBFDF5] shadow-inner scale-110' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

export type UserRole = 'ADMIN' | 'OPERATOR' | 'DRIVER' | 'CUSTOMER';
export type UserStatus = 'PENDING_APPROVAL' | 'APPROVED' | 'SUSPENDED';
export type PaymentMethod = 'CASH' | 'WALLET';
export type VehicleType = 'TOKTOK' | 'MOTORCYCLE' | 'CAR';
export type OrderCategory = 'TAXI' | 'FOOD' | 'PHARMACY' | 'GROCERY' | 'PARCEL';

export enum OrderStatus {
  PENDING = 'PENDING',
  WAITING_FOR_OFFERS = 'WAITING_FOR_OFFERS',
  ACCEPTED = 'ACCEPTED',
  PICKED_UP = 'PICKED_UP',
  ON_THE_WAY = 'ON_THE_WAY',
  DELIVERED = 'DELIVERED',
  DELIVERED_RATED = 'DELIVERED_RATED',
  CANCELLED = 'CANCELLED'
}

export interface Ad {
  id: string;
  title: string;
  description: string;
  imageUrl: string;
  ctaText: string; // نص الزر مثل "اطلب الآن"
  type: 'special_offer' | 'restaurant' | 'service' | 'general';
  targetId?: string; // ID المطعم أو الخدمة المرتبطة
  targetCategory?: OrderCategory;
  isActive: boolean;
  displayOrder: number;
  views: number;
  clicks: number;
  createdAt: number;
}

export interface MenuItem {
  id: string;
  name: string;
  price: number;
  description?: string;
  photoURL?: string;
}

export interface Restaurant {
  id: string;
  name: string;
  category: string;
  address: string;
  lat: number;
  lng: number;
  photoURL?: string;
  menuImageURL?: string;
  menu: MenuItem[];
  isOpen: boolean;
  isFeatured?: boolean;
  promoText?: string;
}

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface Offer {
  id: string;
  orderId: string;
  driverId: string;
  driverName: string;
  driverPhone: string;
  driverRating: number;
  driverPhoto?: string;
  vehicleType: VehicleType;
  price: number;
  createdAt: number;
}

export interface Village {
  id: string;
  name: string;
  center: { lat: number, lng: number };
}

export interface District {
  id: string;
  name: string;
  villages: Village[];
}

export interface User {
  id: string;
  email: string;
  phone: string;
  name: string;
  role: UserRole;
  status: UserStatus;
  photoURL?: string;
  vehicleType?: VehicleType;
  zoneId?: string;
  wallet: {
    balance: number;
    totalEarnings: number;
    withdrawn: number;
  };
  location?: {
    lat: number;
    lng: number;
    heading?: number | null;
    updatedAt: number;
  };
}

export interface Order {
  id: string;
  customerId: string;
  customerPhone: string;
  driverId?: string;
  driverName?: string;
  driverPhone?: string;
  driverPhoto?: string;
  driverRating?: number;
  category: OrderCategory;
  pickup: { address: string; lat: number; lng: number; villageName?: string };
  dropoff: { address: string; lat: number; lng: number; villageName?: string };
  status: OrderStatus;
  price: number;
  distance: number;
  createdAt: number;
  paymentMethod: PaymentMethod;
  requestedVehicleType: VehicleType;
  foodItems?: CartItem[];
  restaurantId?: string;
  restaurantName?: string;
  pickupNotes?: string;
  dropoffNotes?: string;
  passengerCount?: number;
  prescriptionImage?: string;
  notes?: string;
  rating?: number;
  feedback?: string;
}

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order } from '../types';
import { OrderStatus } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Bike, MapPin, Loader2, Power, 
  MessageCircle, History, X,
  PhoneCall, User as UserIcon, Home, 
  ShieldAlert, Bot, Zap, Car, Map as MapIcon,
  AlertTriangle, ExternalLink, Navigation
} from 'lucide-react';

// React Leaflet
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import L from 'leaflet';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, where, onSnapshot, updateDoc, 
  doc, addDoc, getDoc, deleteField
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Components
import ChatView from '../components/ChatView';
import ActivityView from './ActivityView';
import ProfileView from './ProfileView';

const createDriverIcon = (type: string, heading: number = 0) => {
  let emoji = '🛵';
  if (type === 'CAR') emoji = '🚗';
  if (type === 'TOKTOK') emoji = '🛺';

  return L.divIcon({ 
    html: `<div class="bg-white p-2 rounded-full shadow-2xl border-4 border-emerald-500 animate-pulse text-xl flex items-center justify-center transition-transform duration-500" style="transform: rotate(${heading}deg)">${emoji}</div>`, 
    className: 'custom-driver-icon', 
    iconSize: [45, 45], 
    iconAnchor: [22, 22] 
  });
};

const pickupIcon = L.divIcon({ html: `<div class="bg-white p-2 rounded-full shadow-lg border-4 border-rose-500 text-lg flex items-center justify-center">📍</div>`, className: 'pickup-icon', iconSize: [40, 40], iconAnchor: [20, 20] });

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showOfferInput, setShowOfferInput] = useState<string | null>(null);
  const [offerPrice, setOfferPrice] = useState<string>('');
  const [showChat, setShowChat] = useState(false);
  const adminWhatsApp = "201065019364";
  const [currentLocation, setCurrentLocation] = useState({ lat: 30.556, lng: 31.008, heading: 0 });
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (isOnline && "geolocation" in navigator) {
      watchId.current = navigator.geolocation.watchPosition((pos) => {
        const { latitude, longitude, heading } = pos.coords;
        setCurrentLocation({ lat: latitude, lng: longitude, heading: heading || 0 });
        updateDoc(doc(db, "users", user.id), { 
          location: { 
            lat: latitude, 
            lng: longitude, 
            heading: heading || 0,
            updatedAt: Date.now() 
          } 
        });
      }, null, { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 });
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snap) => setAvailableOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]));
    onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [isOnline, user.id, user.status]);

  const handleRejectOrder = async () => {
    if (!activeOrder) return;
    if (!window.confirm("هل تريد الاعتذار عن المشوار؟ سيتم إبلاغ الإدارة فوراً.")) return;
    setIsSubmitting(true);
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.WAITING_FOR_OFFERS, driverId: null, driverName: null, driverPhone: null, acceptedAt: null });
      const rejectMsg = `*⚠️ اعتذار كابتن عن مشوار*\n👤 *الكابتن:* ${user.name}\n📞 *هاتفه:* ${user.phone}\n🆔 *الطلب:* ${activeOrder.id.slice(-6)}\n_المشوار عاد لسوق الطلبات المتاحة._`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(rejectMsg)}`, '_blank');
      alert('تم الاعتذار بنجاح');
    } catch (e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const contactSupport = () => {
    const msg = `أنا الكابتن ${user.name}، لدي مشكلة في المشوار الحالي رقم #${activeOrder?.id.slice(-6)}.`;
    window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(msg)}`, '_blank');
  };

  if (user.status !== 'APPROVED') return <div className="p-12 text-center font-black space-y-6"><ShieldAlert className="h-20 w-20 mx-auto text-emerald-600 animate-bounce" /><h2 className="text-3xl tracking-tighter">حسابك بانتظار التفعيل</h2><button onClick={() => window.open('https://wa.me/201065019364')} className="w-full bg-[#25D366] text-white py-6 rounded-[2rem] font-black shadow-xl">تواصل عبر واتساب</button></div>;
  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout relative">
      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in duration-500">
           <MapContainer center={[currentLocation.lat, currentLocation.lng]} zoom={14} zoomControl={false} className="w-full h-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
              <Marker position={[currentLocation.lat, currentLocation.lng]} icon={createDriverIcon(user.vehicleType || 'TOKTOK', currentLocation.heading)}><Popup>أنت هنا</Popup></Marker>
              {activeOrder && <Marker position={[activeOrder.pickup.lat, activeOrder.pickup.lng]} icon={pickupIcon}><Popup>نقطة الاستلام</Popup></Marker>}
           </MapContainer>
        </div>
      )}
      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-12 space-y-8 max-w-2xl mx-auto text-right">
            <div className={`p-8 md:p-10 rounded-[3rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div><h2 className="text-3xl font-black tracking-tighter">{isOnline ? 'نشط الآن' : 'متوقف'}</h2><p className="text-[10px] font-black opacity-60 mt-1 uppercase">كباتن المنوفية</p></div>
