            )}
        </div>
      </div>
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3rem]">
         {[{id: 'HOME', icon: <Home className="h-6 w-6" />, label: 'الرئيسية'}, {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'}, {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'سجلي'}, {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 transition-all ${activeView === tab.id ? 'text-emerald-600' : 'text-slate-300'}`}>
