const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[]) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [showFullMenu, setShowFullMenu] = useState(false);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       <div className="bg-slate-900 p-8 pt-14 text-white flex justify-between items-center shadow-xl shrink-0">
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl hover:bg-white/20 active:scale-90 transition-all"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category} • المنوفية</p>
          </div>
       </div>

       <div className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-slate-50">
          {restaurant.menu?.map(item => (
            <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center group">
               <div className="flex items-center gap-2">
                  <button onClick={() => addToCart(item)} className="p-2 bg-emerald-500 text-white rounded-xl shadow-lg active:scale-75"><Plus className="h-4 w-4" /></button>
                  <span className="font-black w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                  <button onClick={() => removeFromCart(item.id)} className="p-2 bg-rose-50 text-rose-500 rounded-xl active:scale-75"><Minus className="h-4 w-4" /></button>
               </div>
               <div className="text-right flex items-center gap-4 flex-row-reverse">
                  <div className="w-14 h-14 bg-slate-100 rounded-2xl overflow-hidden border border-slate-50">
                     {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <Utensils className="p-4 text-slate-200" />}
                  </div>
                  <div>
                    <p className="font-black text-slate-800 text-sm">{item.name}</p>
                    <p className="text-xs font-bold text-emerald-600">{item.price} ج.م</p>
                  </div>
               </div>
            </div>
          ))}
       </div>

       {cart.length > 0 && (
         <div className="p-8 bg-white border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-2xl shrink-0">
            <button onClick={() => onCheckout(cart)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-6 w-6" /> تأكيد (إجمالي: {total} ج.م)
            </button>
         </div>
       )}
    </div>
  );
};

