// --- Main Dashboard ---

const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'MAP' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  // Tracking states
  const [driverLocation, setDriverLocation] = useState<{ lat: number, lng: number, heading: number } | null>(null);
  const [eta, setEta] = useState<number | null>(null);
  const [remainingDist, setRemainingDist] = useState<number | null>(null);
  const lastEtaUpdate = useRef<number>(0);

  const adminWhatsApp = "201065019364";

  // متابعة حالة الطلبات النشطة
  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]));
    onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      const current = all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
      setActiveOrder(current || null);
    });
  }, [user.id]);

  // متابعة العروض للطلب الجديد
  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  // متابعة موقع الكابتن لحظياً وحساب الوقت المتوقع (ETA)
  useEffect(() => {
    if (activeOrder?.driverId && [OrderStatus.ACCEPTED, OrderStatus.PICKED_UP].includes(activeOrder.status)) {
      return onSnapshot(doc(db, "users", activeOrder.driverId), async (docSnap) => {
        const data = docSnap.data();
        if (data?.location) {
          const loc = { 
            lat: data.location.lat, 
            lng: data.location.lng, 
            heading: data.location.heading || 0 
          };
          setDriverLocation(loc);

          // تحديث ETA كل 30 ثانية لتوفير موارد الشبكة
          const now = Date.now();
          if (now - lastEtaUpdate.current > 30000) {
             const target = activeOrder.status === OrderStatus.ACCEPTED ? activeOrder.pickup : activeOrder.dropoff;
             if (target) {
                const info = await getRoadDistance(loc.lat, loc.lng, target.lat, target.lng);
                setEta(info.duration);
                setRemainingDist(info.distance);
                lastEtaUpdate.current = now;
             }
          }
        }
      });
    } else {
      setDriverLocation(null);
      setEta(null);
      setRemainingDist(null);
    }
  }, [activeOrder]);

  const handleCreateOrder = async () => {
    if(!dropoffVillage) return alert('يرجى تحديد وجهة التوصيل');
    setIsSubmitting(true);
    try {
      let orderData: any = {
        customerId: user.id, customerPhone: user.phone, category: selectedCategory,
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), paymentMethod: 'CASH',
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name }
      };

      if (selectedCategory === 'TAXI' && pickupVillage) {
        const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
        const price = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
        orderData = { ...orderData, pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name }, distance: dist, price, requestedVehicleType: 'TOKTOK' };
      }

      await addDoc(collection(db, "orders"), orderData);

      const waMsg = `*📢 طلب جديد من وصلها*\n👤 *العميل:* ${user.name}\n📂 *النوع:* ${selectedCategory}\n🏁 *الوجهة:* ${dropoffVillage.name}`;
      window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
    } catch (e) { alert('خطأ في الطلب'); } finally { setIsSubmitting(false); }
  };

  const handleCancelOrder = async () => {
    if (!activeOrder) return;
    if (!window.confirm("هل تريد إلغاء الطلب؟")) return;
    await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED, cancelledAt: Date.now() });
    alert('تم إلغاء الطلب بنجاح');
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout relative h-full w-full">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />

      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={() => {}} />}

      {/* خريطة التتبع المتقدمة */}
      {activeView === 'MAP' && (
        <div className="map-page-container animate-in fade-in">
           <div className="absolute top-6 left-6 z-[1000] flex flex-col gap-3">
              <button onClick={() => setActiveView('NEW')} className="bg-slate-900 text-white p-4 rounded-2xl shadow-2xl flex items-center gap-2 font-black text-xs active:scale-90 transition-all border border-white/10">
                 <ArrowRight className="h-5 w-5" /> العودة للوحة التتبع
              </button>
           </div>

           <MapContainer center={driverLocation ? [driverLocation.lat, driverLocation.lng] : [30.298, 30.975]} zoom={16} zoomControl={false} className="w-full h-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />

              {/* موقع الكابتن الدوار */}
              {driverLocation && (
                <Marker position={[driverLocation.lat, driverLocation.lng]} icon={createDriverIcon(activeOrder?.requestedVehicleType || 'TOKTOK', driverLocation.heading)}>
                   <Popup>
                      <div className="text-right p-2 font-black">
                         الكابتن {activeOrder?.driverName}
                         <div className="text-[10px] text-emerald-600 mt-1">{eta ? `يصل خلال ${eta} دقائق` : 'جاري التحرك...'}</div>
                      </div>
                   </Popup>
                   <RecenterMap coords={[driverLocation.lat, driverLocation.lng]} />
                </Marker>
              )}

              {/* نقاط الرحلة */}
              {activeOrder?.pickup?.lat && (
                <Marker position={[activeOrder.pickup.lat, activeOrder.pickup.lng]} icon={pickupIcon}>
                   <Popup><div className="text-right font-bold">نقطة استلام الطلب</div></Popup>
                </Marker>
              )}
              {activeOrder?.dropoff?.lat && (
                <Marker position={[activeOrder.dropoff.lat, activeOrder.dropoff.lng]} icon={dropoffIcon}>
                   <Popup><div className="text-right font-bold">وجهة الوصول</div></Popup>
                </Marker>
              )}
           </MapContainer>

           <div className="absolute bottom-28 left-6 right-6 z-[1000]">
              <div className="bg-white/90 backdrop-blur-xl p-8 rounded-[3rem] shadow-2xl border border-white flex justify-between items-center flex-row-reverse animate-reveal transition-all">
                 <div className="text-right space-y-1">
                    <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">حالة الرحلة المباشرة</p>
                    <h4 className="text-xl font-black text-slate-900">{activeOrder?.status === OrderStatus.PICKED_UP ? 'جاري توصيل طلبك' : 'الكابتن في طريقه إليك'}</h4>
                    {eta !== null && (
                       <div className="flex items-center gap-2 flex-row-reverse mt-2">
                          <Timer className="h-4 w-4 text-emerald-500" />
                          <span className="font-black text-sm text-emerald-600">الوقت المتبقي: {eta} دقائق</span>
                       </div>
                    )}
                 </div>
                 <div className="bg-emerald-500 text-white p-5 rounded-[2rem] shadow-xl animate-bounce">
                    <Bike className="h-7 w-7" />
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* الواجهة الرئيسية */}
      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 md:p-10 space-y-10 max-xl mx-auto text-right">
          {!activeOrder ? (
            <>
              {/* Header */}
              <div className="flex items-center justify-between">
                 <div className="text-right">
                    <h2 className="text-5xl font-black text-[#0F172A] tracking-tighter">وصـــلــهــا</h2>
                    <p className="text-slate-400 font-bold text-[11px] uppercase tracking-widest mt-1.5 opacity-80">أفضل خدمة توصيل في المنوفية</p>
                 </div>
                 <button onClick={() => setAiOpen(true)} className="p-4 bg-[#EBFDF5] text-[#2D9469] rounded-[1.5rem] shadow-sm active:scale-90 transition-all border border-emerald-50"><Bot className="h-7 w-7" /></button>
              </div>

              {/* Trip Categories */}
              <div className="flex justify-center gap-5">
                  {[
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> },
                    { id: 'TAXI', label: 'مشوار', icon: <Bike /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`w-28 h-36 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 bg-white card-shadow category-btn ${selectedCategory === cat.id ? 'active' : 'opacity-40 grayscale'}`}>
                       <div className={`p-4 rounded-full transition-colors ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>{cat.icon}</div>
                       <span className={`text-xs font-black ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-400'}`}>{cat.label}</span>
                    </button>
                  ))}
              </div>

              {/* Trip Selection Form */}
              <div className="space-y-6">
                 {selectedCategory === 'TAXI' && <VillageInput label="نقطة الانطلاق" helper="أين أنت الآن لاستلامك؟" icon={<MapPin />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />}
                 <VillageInput label="وجهة الوصول" helper="إلى أين نتوجه بك اليوم؟" icon={<Check />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />

                 <button onClick={handleCreateOrder} disabled={isSubmitting || !dropoffVillage} className="w-full py-8 bg-[#10b981] text-white rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                    {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : 'اطلب مشوارك الآمن'}
                 </button>
              </div>
            </>
          ) : (
            /* تتبع الرحلة المباشرة مع خريطة مصغرة */
            <div className="space-y-12 animate-reveal pb-24">
                {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="space-y-12 text-center py-10">
                    <div className="bg-white p-16 rounded-full card-shadow inline-block animate-pulse border-8 border-emerald-50"><Navigation2 className="h-24 w-24 text-emerald-600" /></div>
                    <div className="space-y-2">
                       <h2 className="text-4xl font-black text-slate-900 tracking-tighter">جاري جلب العروض...</h2>
                       <p className="text-slate-400 font-bold text-sm">نبحث لك عن أقرب كابتن في مراكز المنوفية</p>
                    </div>
                    <div className="space-y-4 px-2">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-8 rounded-[3rem] card-shadow flex justify-between items-center border-2 border-emerald-50 animate-in zoom-in">
                            <div className="text-center space-y-2">
                               <p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p>
                               <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, status: OrderStatus.ACCEPTED, price: offer.price, driverPhoto: offer.driverPhoto, acceptedAt: Date.now() })} className="bg-emerald-600 text-white px-10 py-3 rounded-2xl font-black text-sm shadow-lg">قبول</button>
                            </div>
                            <div className="flex items-center gap-4 flex-row-reverse text-right">
                               <div className="w-16 h-16 bg-slate-950 text-emerald-400 rounded-2xl flex items-center justify-center font-black overflow-hidden shadow-md">
                                 {offer.driverPhoto ? <img src={offer.driverPhoto} className="w-full h-full object-cover" /> : 'ك'}
                               </div>
                               <div><p className="font-black text-slate-900 text-xl">{offer.driverName}</p><div className="flex items-center gap-2 text-amber-500 font-black text-xs bg-amber-50 px-4 py-1.5 rounded-full inline-flex">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={handleCancelOrder} className="text-rose-500 font-black text-xs uppercase hover:underline">إلغاء الطلب</button>
                 </div>
                ) : activeOrder.status === OrderStatus.DELIVERED ? (
                  <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                     <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto animate-bounce" />
                     <h2 className="text-3xl font-black text-slate-950">وصلت بالسلامة!</h2>
                     <button onClick={async () => await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now() })} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl">تأكيد الاستلام <ThumbsUp className="h-8 w-8 inline mr-2" /></button>
                  </div>
                ) : (
                  <div className="space-y-8">
                     <div className="bg-[#2D9469] p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                        <div className="text-right">
                           <p className="text-xs font-black opacity-60 uppercase mb-2">تتبع الكابتن المباشر</p>
                           <h3 className="text-2xl font-black leading-tight">{activeOrder.status === OrderStatus.PICKED_UP ? 'جاري توصيلك للوجهة' : 'الكابتن قادم لاستلامك'}</h3>
                           {eta !== null && <p className="text-xs font-bold text-emerald-100 mt-1 flex items-center gap-2 flex-row-reverse"><Timer className="h-3 w-3" /> الموعد: خلال {eta} دقائق</p>}
                        </div>
                        <button onClick={() => setActiveView('MAP')} className="bg-white/20 p-5 rounded-full animate-pulse shadow-inner border border-white/10">
                           <LocateFixed className="h-8 w-8" />
                        </button>
                     </div>

                     {/* Mini Map View */}
                     <div onClick={() => setActiveView('MAP')} className="h-48 bg-slate-100 rounded-[3rem] overflow-hidden shadow-inner border-2 border-slate-50 relative group cursor-pointer">
                        <div className="absolute inset-0 bg-black/5 group-hover:bg-transparent transition-all z-10"></div>
                        <div className="absolute top-4 left-4 z-20 bg-white/90 backdrop-blur px-4 py-2 rounded-xl text-[10px] font-black flex items-center gap-2 shadow-sm">
                           <MapIcon className="h-3 w-3 text-emerald-500" /> عرض الخريطة كاملة
                        </div>
                        <MapContainer center={driverLocation ? [driverLocation.lat, driverLocation.lng] : [30.298, 30.975]} zoom={14} zoomControl={false} className="w-full h-full grayscale-[0.2]">
                           <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
                           {driverLocation && <Marker position={[driverLocation.lat, driverLocation.lng]} icon={createDriverIcon(activeOrder.requestedVehicleType, driverLocation.heading)} />}
                        </MapContainer>
                     </div>

                     <div className="flex flex-col items-center gap-6">
                        <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">
                           {activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}
                        </div>
                        <div className="text-center">
                           <h4 className="text-3xl font-black text-slate-950 tracking-tight">{activeOrder.driverName}</h4>
                           <div className="flex items-center justify-center gap-2 mt-2">
                             <div className="flex items-center gap-1 text-amber-500 bg-amber-50 px-4 py-1.5 rounded-full font-black text-xs">
                                {activeOrder.driverRating || 5.0} <Star className="h-3 w-3 fill-amber-400" />
                             </div>
                             <span className="bg-emerald-50 text-emerald-600 px-6 py-1.5 rounded-full font-black text-[10px] uppercase">كابتن وصلها المعتمد</span>
                           </div>
                        </div>
                     </div>

                     <div className="grid grid-cols-2 gap-4">
                        <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-6 rounded-3xl font-black text-sm flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all"><PhoneCall className="h-5 w-5" /> اتصال مباشر</a>
                        <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-6 rounded-3xl font-black text-sm flex items-center justify-center gap-3 active:scale-95 transition-all"><MessageCircle className="h-5 w-5" /> دردشة الرحلة</button>
                     </div>

                     <div className="pt-4 flex flex-col gap-3">
                        <button onClick={handleCancelOrder} className="w-full py-4 text-rose-500 font-black text-xs uppercase flex items-center justify-center gap-2 hover:bg-rose-50 rounded-2xl transition-all">
                           <AlertTriangle className="h-4 w-4" /> إلغاء الرحلة
                        </button>
                     </div>
                  </div>
                )}
            </div>
          )}
        </div>
      </div>

      {/* Navigation */}
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3.5rem]">
         {[
           {id: 'NEW', icon: <Plus className="h-6 w-6" />, label: 'طلب جديد'},
           {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-[#EBFDF5] shadow-inner scale-110' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;800;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-blue: #0085C7;
  --brand-dark: #0F172A;
  --bg-light: #F8FAFC;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: var(--bg-light);
  color: #1E293B;
  -webkit-font-smoothing: antialiased;
  overflow: hidden;
  height: 100vh;
  width: 100vw;
  position: fixed;
}

/* تحريك سلس لأيقونات الخريطة */
.custom-driver-icon {
  transition: all 1.5s cubic-bezier(0.4, 0, 0.2, 1);
  background: none !important;
  border: none !important;
}

.custom-driver-icon div {
  transition: transform 0.8s ease-out;
}

.leaflet-marker-icon {
  transition: transform 1.2s linear;
}

/* Base Layout Containers */
.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  height: calc(100vh - 65px);
  overflow: hidden;
}

@media (min-width: 768px) {
  .main-content {
    height: calc(100vh - 80px);
  }
}

.card-shadow {
  box-shadow: 0 10px 30px -5px rgba(0, 0, 0, 0.05);
}

.category-btn {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.category-btn.active {
  border: 3px solid #10b981;
  transform: scale(1.05);
}

.page-container {
  flex: 1;
  overflow-y: auto;
  padding-bottom: 120px;
  background: var(--bg-light);
}

.map-page-container {
  position: absolute;
  inset: 0;
  z-index: 10;
  padding-bottom: 80px;
}

.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

button:active { transform: scale(0.96); }

@keyframes glow {
  0% { box-shadow: 0 0 5px rgba(16, 185, 129, 0.2); }
  50% { box-shadow: 0 0 25px rgba(16, 185, 129, 0.6); }
  100% { box-shadow: 0 0 5px rgba(16, 185, 129, 0.2); }
}
.animate-glow { animation: glow 2s ease-in-out infinite; }

@keyframes pulse-emerald {
  0% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.2); opacity: 0.5; }
  100% { transform: scale(1); opacity: 1; }
}
.animate-pulse-emerald { animation: pulse-emerald 2s infinite; }

import React, { useState, useEffect, useRef } from 'react';

// Types
import type { User, Order } from '../types';
import { OrderStatus } from '../types';

// Services
import { db } from '../services/firebase';
import { 
  collection, query, onSnapshot, orderBy, doc, 
  updateDoc, where, getDocs, limit 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Utils
import { stripFirestore } from '../utils';

// Icons
import { 
  Activity, Bike, X, MapPin, Phone, ChevronRight, Clock, 
  Zap, Loader2, XCircle, Map as MapIcon,
  Search, ShieldCheck, MessageCircle, ArrowUp, Navigation
} from 'lucide-react';

// Map
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';

const driverIcon = (type: string, name: string) => L.divIcon({
  html: `<div class="flex flex-col items-center">
            <div class="bg-white px-2 py-1 rounded-lg shadow-lg border border-slate-100 text-[8px] font-black mb-1 whitespace-nowrap">${name}</div>
            <div class="bg-slate-900 p-2 rounded-full shadow-2xl border-2 border-emerald-500 text-sm">
               ${type === 'CAR' ? '🚗' : type === 'MOTORCYCLE' ? '🏍️' : '🛺'}
            </div>
         </div>`,
  className: 'custom-driver-icon',
  iconSize: [40, 60],
  iconAnchor: [20, 50]
});

const orderMarkerIcon = L.divIcon({
  html: `<div class="bg-rose-500 p-2 rounded-full shadow-2xl border-2 border-white animate-bounce text-xs">📦</div>`,
  className: 'order-icon',
  iconSize: [30, 30],
  iconAnchor: [15, 15]
});

const OperatorDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [orders, setOrders] = useState<Order[]>([]);
  const [drivers, setDrivers] = useState<User[]>([]);
  const [activeTab, setActiveTab] = useState<'LIVE' | 'MAP' | 'DRIVERS' | 'HISTORY'>('LIVE');
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const [showScrollTop, setShowScrollTop] = useState(false);

  useEffect(() => {
    const unsubOrders = onSnapshot(query(collection(db, "orders"), orderBy("createdAt", "desc"), limit(100)), (snap) => {
      setOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubDrivers = onSnapshot(query(collection(db, "users"), where("role", "==", "DRIVER")), (snap) => {
      setDrivers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as User[]);
    });
    return () => { unsubOrders(); unsubDrivers(); };
  }, []);

  const liveOrders = orders.filter(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status));
  const activeDrivers = drivers.filter(d => d.location && (Date.now() - (d.location.updatedAt || 0) < 300000)); // ظهروا آخر 5 دقائق

  return (
    <div ref={scrollContainerRef} onScroll={(e) => setShowScrollTop(e.currentTarget.scrollTop > 400)} className="h-full overflow-auto scroll-smooth relative bg-[#f8fafc]" dir="rtl">
      <div className="max-w-7xl mx-auto space-y-6 md:space-y-10 pb-40 p-4 md:p-6 animate-in fade-in duration-700 text-right">

        {/* Header */}
        <div className="bg-white p-6 md:p-8 rounded-[2.5rem] md:rounded-[3.5rem] shadow-xl border border-slate-100 flex flex-col lg:flex-row-reverse justify-between items-center gap-6 sticky top-0 z-[100] backdrop-blur-xl bg-white/95">
           <div className="flex items-center gap-4">
              <div className="text-right">
                 <h2 className="text-2xl md:text-3xl font-black text-slate-950 tracking-tighter">تحكم المنوفية</h2>
                 <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">المراقبة المركزية</p>
              </div>
              <div className="bg-slate-900 p-4 rounded-[1.5rem] text-emerald-400"><Activity className="h-8 w-8 animate-pulse" /></div>
           </div>
           <div className="flex gap-2 bg-slate-50 p-2 rounded-[2rem] shadow-inner overflow-x-auto no-scrollbar w-full lg:w-auto">
              {[
                { id: 'LIVE', label: 'النشاط', icon: <Zap className="h-4 w-4" /> },
                { id: 'MAP', label: 'خريطة حية', icon: <MapIcon className="h-4 w-4" /> },
                { id: 'DRIVERS', label: 'الكباتن', icon: <Bike className="h-4 w-4" /> },
                { id: 'HISTORY', label: 'السجل', icon: <Clock className="h-4 w-4" /> }
              ].map(tab => (
                <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`px-8 py-4 rounded-[1.5rem] text-[10px] font-black transition-all flex items-center gap-2 whitespace-nowrap ${activeTab === tab.id ? 'bg-slate-950 text-white shadow-2xl' : 'text-slate-400 hover:text-slate-950'}`}>
                  {tab.icon} {tab.label}
                </button>
              ))}
           </div>
        </div>

        {/* Tab Content */}
        {activeTab === 'MAP' ? (
          <div className="h-[600px] rounded-[3.5rem] overflow-hidden shadow-2xl border-8 border-white relative animate-in zoom-in duration-500">
             <MapContainer center={[30.556, 31.008]} zoom={12} zoomControl={false} className="w-full h-full">
                <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />

                {/* الكباتن النشطين */}
                {activeDrivers.map(d => (
                  <Marker key={d.id} position={[d.location!.lat, d.location!.lng]} icon={driverIcon(d.vehicleType || 'TOKTOK', d.name)}>
                    <Popup>
                       <div className="text-right p-2">
                          <p className="font-black text-slate-900">{d.name}</p>
                          <p className="text-[10px] text-emerald-600 mt-1">متصل الآن</p>
                          <a href={`tel:${d.phone}`} className="mt-2 block bg-slate-900 text-white p-2 rounded-lg text-center text-[10px]">اتصال</a>
                       </div>
                    </Popup>
                  </Marker>
                ))}

                {/* الطلبات الجارية */}
                {liveOrders.map(o => o.pickup && (
                  <Marker key={o.id} position={[o.pickup.lat, o.pickup.lng]} icon={orderMarkerIcon}>
                     <Popup><div className="text-right font-black">طلب من: {o.pickup.villageName}</div></Popup>
                  </Marker>
                ))}
             </MapContainer>
             <div className="absolute top-6 right-6 bg-white/90 backdrop-blur-md p-4 rounded-2xl shadow-xl z-[1000] border border-slate-100">
                <div className="flex items-center gap-3 text-right">
                   <div className="w-3 h-3 rounded-full bg-emerald-500 animate-pulse"></div>
                   <p className="text-[10px] font-black text-slate-800">نشط الآن: {activeDrivers.length} كابتن</p>
                </div>
             </div>
          </div>
        ) : activeTab === 'LIVE' ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
