/**
 * وظيفة متقدمة لتطهير البيانات من أي مراجع دائرية أو كائنات غير قابلة للتسلسل (Non-serializable).
 * تضمن هذه الوظيفة أن الكائنات التي يتم إرسالها إلى Firestore هي كائنات بسيطة (Plain Objects) فقط.
 */
export const stripFirestore = (data: any, seen = new WeakSet()): any => {
  if (data === null || data === undefined) return data;

  const type = typeof data;

  // إذا كان النوع ليس كائناً (Primitive)، نعيده كما هو
  if (type !== 'object') return data;

  // الحماية من المراجع الدائرية
  if (seen.has(data)) return undefined;

  // التعامل مع كائنات التاريخ و Firestore Timestamps
  if (typeof data.toMillis === 'function') return data.toMillis();
  if (typeof data.toDate === 'function') return data.toDate().getTime();
  if (data instanceof Date) return data.getTime();

  // التعامل مع المصفوفات
  if (Array.isArray(data)) {
    seen.add(data);
    return data
      .map(item => stripFirestore(item, seen))
      .filter(val => val !== undefined);
  }

  // التحقق مما إذا كان الكائن كائناً بسيطاً (Plain Object)
  // هذا يمنع الدخول في كائنات معقدة مثل DOM nodes أو Leaflet Map instances أو Google Maps objects
  const isPlainObject = Object.prototype.toString.call(data) === '[object Object]';
  if (!isPlainObject) {
    // إذا لم يكن كائناً بسيطاً، نحاول استخراج القيم الأساسية إذا كان كائناً مغلفاً، وإلا نتجاهله
    return undefined;
  }

  seen.add(data);

  const stripped: any = {};
  for (const key in data) {
    if (Object.prototype.hasOwnProperty.call(data, key)) {
      // تجاهل الخصائص الخاصة بـ Firebase أو أي خصائص تبدأ بـ _ أو $
      if (key.startsWith('_') || key.startsWith('$')) continue;

      const value = data[key];

      // تجاهل الوظائف (Functions)
      if (typeof value === 'function') continue;

      const cleanedValue = stripFirestore(value, seen);
      if (cleanedValue !== undefined) {
        stripped[key] = cleanedValue;
      }
    }
  }

  return stripped;
};

/**
 * حساب المسافة الفعلية عبر الطريق باستخدام OSRM API
 */
export const getRoadDistance = async (lat1: number, lon1: number, lat2: number, lon2: number): Promise<{ distance: number, duration: number }> => {
  try {
    const url = `https://router.project-osrm.org/route/v1/driving/${lon1},${lat1};${lon2},${lat2}?overview=false`;
    const response = await fetch(url);
    const data = await response.json();

    if (data.code === 'Ok' && data.routes && data.routes.length > 0) {
      return {
        distance: parseFloat((data.routes[0].distance / 1000).toFixed(1)),
        duration: Math.ceil(data.routes[0].duration / 60)
      };
    }
    throw new Error('Fallback to Haversine');
  } catch (error) {
    const R = 6371;
    const dLat = (lat2 - lat1) * (Math.PI / 180);
    const dLon = (lon2 - lon1) * (Math.PI / 180);
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + 
              Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * 
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    const straightDistance = R * c;
    return { 
      distance: parseFloat((straightDistance * 1.3).toFixed(1)), 
      duration: Math.ceil(straightDistance * 2.5) 
    };
  }
};

export const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  if (!lat1 || !lon1 || !lat2 || !lon2) return 0;
  const R = 6371; 
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + 
            Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * 
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return parseFloat((R * c).toFixed(1));
};

export const compressImage = (base64Str: string, maxWidth = 800, maxHeight = 800): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.src = base64Str;
    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;
      if (width > height) {
        if (width > maxWidth) { height *= maxWidth / width; width = maxWidth; }
      } else {
        if (height > maxHeight) { width *= maxHeight / height; height = maxHeight; }
      }
      canvas.width = width; canvas.height = height;
      const ctx = canvas.getContext('2d');
      ctx?.drawImage(img, 0, 0, width, height);
      resolve(canvas.toDataURL('image/jpeg', 0.7));
    };
  });
};

export const stripFirestore = (data: any, seen = new WeakSet()): any => {
  if (data === null || data === undefined) return data;

  const type = typeof data;
  if (type !== 'object') return data;
  if (seen.has(data)) return undefined;

  if (typeof data.toMillis === 'function') return data.toMillis();
  if (typeof data.toDate === 'function') return data.toDate().getTime();
  if (data instanceof Date) return data.getTime();

  const isArray = Array.isArray(data);
  const isPlainObject = Object.prototype.toString.call(data) === '[object Object]';

  if (!isArray && !isPlainObject) return undefined;

  seen.add(data);

  if (isArray) {
    return data
      .map(item => stripFirestore(item, seen))
      .filter(val => val !== undefined);
  }

  const stripped: any = {};
  for (const key in data) {
    if (Object.prototype.hasOwnProperty.call(data, key)) {
      if (key.startsWith('_') || key.startsWith('$')) continue;
      if (typeof data[key] === 'function') continue;

      const cleaned = stripFirestore(data[key], seen);
      if (cleaned !== undefined) {
        stripped[key] = cleaned;
      }
    }
  }
  return stripped;
};

export const calculateDistance = (lat1: number, lon1: number, lat2: number, lon2: number): number => {
  if (!lat1 || !lon1 || !lat2 || !lon2) return 0;
  const R = 6371;
  const dLat = (lat2 - lat1) * (Math.PI / 180);
  const dLon = (lon2 - lon1) * (Math.PI / 180);
  const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) + 
            Math.cos(lat1 * (Math.PI / 180)) * Math.cos(lat2 * (Math.PI / 180)) * 
            Math.sin(dLon / 2) * Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return parseFloat((R * c).toFixed(1));
};

