    iconAnchor: [22, 22] 
  });
};

const CourierDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'HOME' | 'MAP' | 'ACTIVITY' | 'PROFILE'>('HOME');
  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [availableOrders, setAvailableOrders] = useState<Order[]>([]);
  const [isOnline, setIsOnline] = useState(true);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [currentLocation, setCurrentLocation] = useState({ lat: 30.556, lng: 31.008, heading: 0 });
  const watchId = useRef<number | null>(null);

  useEffect(() => {
    if (isOnline && "geolocation" in navigator) {
      watchId.current = navigator.geolocation.watchPosition((pos) => {
        const { latitude, longitude, heading } = pos.coords;
        setCurrentLocation({ lat: latitude, lng: longitude, heading: heading || 0 });

        // تحديث الموقع والاتجاه في Firestore
        updateDoc(doc(db, "users", user.id), { 
          location: { 
            lat: latitude, 
            lng: longitude, 
            heading: heading || 0,
            updatedAt: Date.now() 
          } 
        });
      }, null, { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 });
    }
    return () => { if (watchId.current !== null) navigator.geolocation.clearWatch(watchId.current); };
  }, [isOnline, user.id]);

  useEffect(() => {
    if (!isOnline || user.status !== 'APPROVED') return;
    const unsubAvailable = onSnapshot(query(collection(db, "orders"), where("status", "==", OrderStatus.WAITING_FOR_OFFERS)), (snap) => {
      setAvailableOrders(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Order[]);
    });
    const unsubActive = onSnapshot(query(collection(db, "orders"), where("driverId", "==", user.id)), (snap) => {
      const all = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
    return () => { unsubAvailable(); unsubActive(); };
  }, [isOnline, user.id, user.status]);

  if (user.status !== 'APPROVED') return <div className="p-12 text-center space-y-6"><ShieldAlert className="h-20 w-20 mx-auto text-emerald-600 animate-bounce" /><h2 className="text-3xl tracking-tighter">حسابك بانتظار التفعيل</h2></div>;
  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('HOME')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onBack={() => setActiveView('HOME')} onUpdate={() => {}} />;

  return (
    <div className="rh-layout relative">
      {activeView === 'MAP' && (
        <div className="map-page-container">
           <MapContainer center={[currentLocation.lat, currentLocation.lng]} zoom={15} zoomControl={false} className="w-full h-full">
              <TileLayer url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png" />
              <Marker position={[currentLocation.lat, currentLocation.lng]} icon={createDriverIcon(user.vehicleType || 'TOKTOK', currentLocation.heading)} />
           </MapContainer>
           <button onClick={() => setActiveView('HOME')} className="absolute top-6 left-6 z-[1000] bg-slate-900 text-white p-4 rounded-2xl shadow-2xl flex items-center gap-2 font-black text-xs">
              <Navigation className="h-4 w-4" /> رجوع
           </button>
        </div>
      )}

      <div className={`page-container no-scrollbar ${activeView === 'MAP' ? 'hidden' : 'block'}`}>
        <div className="p-6 space-y-8 max-w-2xl mx-auto text-right">
            <div className={`p-8 rounded-[3rem] text-white flex justify-between items-center shadow-2xl transition-all duration-700 ${isOnline ? 'bg-emerald-600' : 'bg-slate-950'}`}>
               <div><h2 className="text-3xl font-black">{isOnline ? 'نشط' : 'متوقف'}</h2></div>
               <button onClick={() => setIsOnline(!isOnline)} className={`p-6 rounded-[2rem] shadow-2xl ${isOnline ? 'bg-white text-emerald-600' : 'bg-emerald-500 text-white'}`}><Power className="h-10 w-10" /></button>
            </div>

            {activeOrder ? (
               <div className="bg-white rounded-[4rem] shadow-2xl border-t-8 border-t-emerald-500 p-8 space-y-8">
                  <div className="flex justify-between items-center"><span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full text-[10px] font-black uppercase">{activeOrder.status}</span><p className="text-4xl font-black">{activeOrder.price} ج.م</p></div>
                  <div className="grid grid-cols-2 gap-4">
                     <a href={`tel:${activeOrder.customerPhone}`} className="bg-slate-950 text-white py-5 rounded-[1.8rem] font-black text-sm flex items-center justify-center gap-3"><PhoneCall className="h-5 w-5" /> اتصال</a>
                     <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 py-5 rounded-[1.8rem] font-black text-sm flex items-center justify-center gap-3"><MessageCircle className="h-5 w-5" /> دردشة</button>
                     <button onClick={async () => { const status = activeOrder.status === OrderStatus.ACCEPTED ? OrderStatus.PICKED_UP : OrderStatus.DELIVERED; await updateDoc(doc(db, "orders", activeOrder.id), { status, deliveredAt: status === OrderStatus.DELIVERED ? Date.now() : undefined }); }} className="col-span-2 bg-emerald-600 text-white py-6 rounded-[2rem] font-black text-lg">
                        {activeOrder.status === OrderStatus.ACCEPTED ? 'تأكيد الاستلام' : 'تأكيد التوصيل'}
                     </button>
                     <button onClick={() => setActiveView('MAP')} className="col-span-2 bg-emerald-50 text-emerald-600 py-4 rounded-2xl font-black text-xs flex items-center justify-center gap-2"><MapIcon className="h-4 w-4" /> الخريطة</button>
                  </div>
               </div>
            ) : (
               <div className="space-y-6">
                  {availableOrders.map(o => (
                     <div key={o.id} className="bg-white p-8 rounded-[3.5rem] border-2 border-slate-50 shadow-xl flex justify-between items-center">
                        <div className="text-right"><p className="text-xl font-black">{o.pickup?.villageName} ← {o.dropoff?.villageName}</p></div>
                        <button onClick={async () => { await addDoc(collection(db, "offers"), { orderId: o.id, driverId: user.id, driverName: user.name, driverPhone: user.phone, driverRating: 5.0, vehicleType: user.vehicleType || 'TOKTOK', price: o.price, createdAt: Date.now() }); }} className="bg-slate-950 text-emerald-400 p-4 rounded-2xl font-black">تقديم عرض</button>
                     </div>
                  ))}
               </div>
            )}
        </div>
      </div>
      <nav className="fixed bottom-0 left-0 right-0 bg-white border-t p-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3rem]">
         {[{id: 'HOME', icon: <Home className="h-6 w-6" />, label: 'الرئيسية'}, {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'}, {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'سجلي'}, {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1 ${activeView === tab.id ? 'text-emerald-600' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 scale-110' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

