              <div className="flex justify-center gap-5">
                  {[{ id: 'PHARMACY', label: 'صيدلية', icon: <Pill /> }, { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed /> }, { id: 'TAXI', label: 'مشوار', icon: <Bike /> }].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`w-28 h-36 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 bg-white card-shadow category-btn ${selectedCategory === cat.id ? 'active' : 'opacity-40 grayscale'}`}>
                       <div className={`p-4 rounded-full ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>{cat.icon}</div>
                       <span className={`text-xs font-black ${selectedCategory === cat.id ? 'text-[#2D9469]' : 'text-slate-400'}`}>{cat.label}</span>
                    </button>
                  ))}
              </div>
              <button onClick={handleCreateOrder} disabled={isSubmitting || !dropoffVillage} className="w-full py-8 bg-[#10b981] text-white rounded-[2.5rem] font-black text-2xl shadow-2xl flex items-center justify-center gap-4">
                 {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : 'اطلب الآن'}
              </button>
            </>
          ) : (
            <div className="space-y-12 animate-reveal">
                {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="space-y-12 text-center py-10">
                    <div className="bg-white p-16 rounded-full card-shadow animate-pulse inline-block"><Navigation2 className="h-24 w-24 text-emerald-600" /></div>
                    <h2 className="text-4xl font-black">جاري جلب العروض...</h2>
                    {incomingOffers.map(offer => (
                      <div key={offer.id} className="bg-white p-8 rounded-[3rem] card-shadow flex justify-between items-center border-2 border-emerald-50">
                         <div className="text-center space-y-2"><p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p><button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone, status: OrderStatus.ACCEPTED, acceptedAt: Date.now() })} className="bg-emerald-600 text-white px-8 py-2 rounded-2xl">قبول</button></div>
                         <div className="text-right font-black"><p className="text-xl">{offer.driverName}</p><div className="text-amber-500 flex items-center gap-1">{offer.driverRating} <Star className="h-3 w-3 fill-amber-500" /></div></div>
                      </div>
                    ))}
                 </div>
                ) : activeOrder.status === OrderStatus.DELIVERED ? (
                  <div className="animate-in zoom-in space-y-8 text-center bg-white p-10 rounded-[4rem] shadow-2xl border-4 border-emerald-500/10">
                     <PartyPopper className="h-20 w-20 text-emerald-500 mx-auto" />
                     <h2 className="text-3xl font-black">وصلت بالسلامة!</h2>
                     <button onClick={async () => await updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.DELIVERED_RATED, ratedAt: Date.now() })} className="w-full bg-[#10b981] text-white py-8 rounded-[3rem] font-black text-2xl shadow-2xl">تأكيد الاستلام</button>
                  </div>
                ) : (
                  <div className="space-y-12">
                     <div className="bg-[#2D9469] p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl">
                        <div className="text-right"><p className="text-xs font-black opacity-60 uppercase mb-2">تتبع الكابتن</p><h3 className="text-2xl font-black leading-tight">{activeOrder.status === OrderStatus.PICKED_UP ? 'جاري التوصيل' : 'الكابتن قادم إليك'}</h3></div>
                        <button onClick={() => setActiveView('MAP')} className="bg-white/20 p-5 rounded-full animate-pulse shadow-inner"><LocateFixed className="h-8 w-8" /></button>
                     </div>
                     <div className="flex flex-col items-center gap-6">
                        <div className="w-32 h-32 bg-slate-100 rounded-[3rem] flex items-center justify-center border-8 border-white shadow-2xl overflow-hidden">{activeOrder.driverPhoto ? <img src={activeOrder.driverPhoto} className="w-full h-full object-cover" /> : <UserIcon className="h-14 w-14 text-slate-300" />}</div>
                        <div className="text-center"><h4 className="text-3xl font-black text-slate-950">{activeOrder.driverName}</h4></div>
                     </div>
                     <div className="grid grid-cols-2 gap-4">
                        <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-6 rounded-3xl font-black text-sm flex items-center justify-center gap-3 shadow-xl"><PhoneCall className="h-5 w-5" /> اتصال</a>
                        <button onClick={() => setShowChat(true)} className="bg-white border-2 border-slate-100 text-slate-900 py-6 rounded-3xl font-black text-sm flex items-center justify-center gap-3"><MessageCircle className="h-5 w-5" /> دردشة</button>
                     </div>
                     <button onClick={() => setActiveView('MAP')} className="w-full bg-emerald-50 text-emerald-600 py-6 rounded-3xl font-black text-lg flex items-center justify-center gap-3 border-2 border-emerald-100 shadow-sm"><MapIcon className="h-6 w-6" /> فتح الخريطة كاملة</button>
                     <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="w-full py-4 text-rose-500 font-black text-xs uppercase flex items-center justify-center gap-2 hover:bg-rose-50 rounded-2xl">إلغاء الرحلة</button>
                  </div>
                )}
            </div>
          )}
        </div>
      </div>
      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-6 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse rounded-t-[3.5rem]">
         {[
           {id: 'NEW', icon: <Plus className="h-6 w-6" />, label: 'طلب جديد'},
           {id: 'MAP', icon: <MapIcon className="h-6 w-6" />, label: 'الخريطة'},
           {id: 'ACTIVITY', icon: <History className="h-6 w-6" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-6 w-6" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-1.5 transition-all border-none bg-transparent ${activeView === tab.id ? 'text-[#2D9469]' : 'text-slate-300'}`}>
              <div className={`p-3.5 rounded-2xl transition-all ${activeView === tab.id ? 'bg-[#EBFDF5] shadow-inner scale-110' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;
